GEO_NEW_COURSES = [{'id': 'g7', 'no': '3.1', 'subject': '地理', 'title': '水循环', 'subtitle': '水循环的类型、环节与地理意义', 'color': '#1f8a8a', 'points': [{'head': '① 水圈的组成', 'body': '地球上的水按其存在空间分为<b>海洋水、陆地水、大气水</b>。其中<b>海洋水约占全球水储量的 96.5%</b>，是水圈的主体；陆地水中<b>冰川</b>是淡水的主体，人类较易利用的是河流水、淡水湖泊水和浅层地下水；大气水数量最少但更新最快。', 'tip': '两个数字必记：海洋水约 96.5%、淡水主体是冰川。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="96.0" width="256" height="42.0" fill="#eaf6f6" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="121.0" font-size="11.5" font-weight="700" fill="#1c5f5f">大气水</text><text x="284" y="121.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">更新最快</text><rect x="34" y="54.0" width="256" height="42.0" fill="#dceeee" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="79.0" font-size="11.5" font-weight="700" fill="#1c5f5f">陆地水</text><text x="284" y="79.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">冰川为主体</text><rect x="34" y="12.0" width="256" height="42.0" fill="#cfe6e6" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="37.0" font-size="11.5" font-weight="700" fill="#1c5f5f">海洋水</text><text x="284" y="37.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">约96.5%</text><line x1="34" y1="12" x2="34" y2="138" stroke="#1f8a8a" stroke-width="1.6"/><text x="22" y="75.0" font-size="9.5" fill="#1f8a8a" text-anchor="middle" transform="rotate(-90 22 75.0)">海拔升高</text></svg>'}, {'head': '② 水循环的概念', 'body': '<b>水循环</b>是指自然界的水在<b>水圈、大气圈、岩石圈、生物圈</b>四大圈层中，通过<b>蒸发、水汽输送、降水、下渗、径流</b>等环节连续运动的过程。它把四大圈层联系成一个有机整体。', 'tip': '水循环是自然地理环境整体性的典型案例，综合题常用。'}, {'head': '③ 水循环的三种类型', 'body': '按发生的空间范围，水循环可分为：<b>海陆间循环</b>（最重要，使陆地淡水不断补充更新）、<b>陆地内循环</b>（发生在陆地与陆地上空，如内流河、内陆湖区域）、<b>海上内循环</b>（发生在海洋与海洋上空，参与水量最大）。', 'tip': '对比记忆：水量最大的是海上内循环；对陆地最关键的是海陆间循环。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1f8a8a" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1f8a8a"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">Ⅰ</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">海陆间循环</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">Ⅱ</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">陆地内循环</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">Ⅲ</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">海上内循环</text></svg>'}, {'head': '④ 水循环的主要环节', 'body': '以海陆间循环为例，包括六大环节：<b>蒸发</b>（含植物<b>蒸腾</b>）→ <b>水汽输送</b> → <b>降水</b> → <b>地表径流</b>、<b>下渗</b> → <b>地下径流</b>，最后汇入海洋，循环往复。', 'tip': '顺序题主线：蒸发—输送—降水—径流，别漏掉下渗。', 'svg': '<svg viewBox="0 0 320 184" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">蒸发、植物蒸腾→水汽进入大气</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">水汽输送→由海洋上空到陆地上空</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">降水→凝结成雨雪降落地表</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">地表径流→汇入江河再入海洋</text><path d="M160 138 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="146" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="164" font-size="11.5" fill="#4a4238">下渗→地下径流→返回海洋</text></svg>'}, {'head': '⑤ 水循环的动力与成因', 'body': '水循环能够发生的内因是水在常温常压下能发生<b>固、液、气三态转化</b>；外因（动力）来自<b>太阳辐射</b>（提供蒸发所需的能量）和<b>水的重力</b>（使降水落地、径流由高处流向低处）。', 'tip': '动力双来源：太阳辐射 + 重力，答题两个都要写。'}, {'head': '⑥ 水循环的地理意义', 'body': '① 维持全球水的<b>动态平衡</b>；② <b>更新陆地水资源</b>，使淡水得以再生；③ 通过径流<b>塑造地表形态</b>（河流侵蚀形成河谷、堆积形成三角洲）；④ <b>输送热量、泥沙和盐类</b>等物质能量，调节全球热量平衡；⑤ 影响全球的<b>气候</b>与生态环境。', 'tip': '意义题按水量—更新—地貌—物质能量—气候五条线索作答。'}, {'head': '⑦ 人类活动对水循环的影响', 'body': '人类主要通过改变水循环的<b>某些环节</b>来影响水循环。有利：修<b>水库</b>（调节径流季节分配）、<b>跨流域调水</b>（改变水资源空间分布）、植树造林、建设<b>海绵城市</b>增加下渗。不利：过度抽取地下水导致地面沉降、围湖造田削弱湖泊调蓄能力、城市地面硬化使下渗减少、内涝多发。', 'tip': '城市化的典型后果：下渗减少、地表径流增加→城市内涝。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">城市硬化地面增多</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">下渗减少、地表径流增多</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">暴雨时排水不畅</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">城市内涝风险增大</text></svg>'}, {'head': '⑧ 河流的主要补给类型', 'body': '河水的来源即<b>补给类型</b>：<b>雨水补给</b>（我国东部季风区最主要，形成夏汛）；<b>季节性积雪融水</b>（东北地区形成春汛）；<b>冰川融水</b>（西北内陆河流，夏季径流量最大、冬季断流）；<b>湖泊水与地下水</b>（补给较稳定，起到削峰补枯的调节作用）。', 'tip': '口诀：东部夏汛靠雨水，东北春汛靠积雪，西北夏汛靠冰川，湖泊地下水稳全年。'}], 'videos': [{'name': '《水循环》科普讲解动画', 'type': '讲解视频', 'level': '必看', 'kw': '水循环 科普动画 高中地理', 'note': '把三类水循环与六大环节一次看懂', 'seg': '全片约 15 分钟', 'covers': '②③④⑤', 'minutes': 15}, {'name': '《地球上的水》纪录片', 'type': '纪录片', 'level': '选看', 'kw': '地球上的水 纪录片 水资源', 'note': '理解水圈构成与水资源的更新', 'seg': '看前 20 分钟', 'covers': '①⑥', 'minutes': 20}, {'name': '海绵城市与城市内涝科普', 'type': '科普视频', 'level': '补充', 'kw': '海绵城市 下渗 城市内涝 科普', 'note': '看人类如何影响水循环的具体环节', 'seg': '10 分钟', 'covers': '⑦', 'minutes': 10}], 'quiz': [{'q': '地球上的水体中，储量最大的是（\u3000）', 'o': ['海洋水', '冰川', '河流水', '大气水'], 'a': 0, 'e': '海洋水约占全球水储量的 96.5%，储量最大。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="96.0" width="256" height="42.0" fill="#eaf6f6" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="121.0" font-size="11.5" font-weight="700" fill="#1c5f5f">大气水</text><text x="284" y="121.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">更新最快</text><rect x="34" y="54.0" width="256" height="42.0" fill="#dceeee" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="79.0" font-size="11.5" font-weight="700" fill="#1c5f5f">陆地水</text><text x="284" y="79.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">冰川为主体</text><rect x="34" y="12.0" width="256" height="42.0" fill="#cfe6e6" stroke="#1f8a8a" stroke-width="1"/><text x="42" y="37.0" font-size="11.5" font-weight="700" fill="#1c5f5f">海洋水</text><text x="284" y="37.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">约96.5%</text><line x1="34" y1="12" x2="34" y2="138" stroke="#1f8a8a" stroke-width="1.6"/><text x="22" y="75.0" font-size="9.5" fill="#1f8a8a" text-anchor="middle" transform="rotate(-90 22 75.0)">海拔升高</text></svg>'}, {'q': '陆地淡水的主体是（\u3000）', 'o': ['河流水', '淡水湖泊水', '冰川', '地下水'], 'a': 2, 'e': '冰川是陆地淡水的主体，约占淡水总量的三分之二。'}, {'q': '水循环的动力主要来自（\u3000）', 'o': ['只有太阳辐射', '只有地球重力', '太阳辐射和水的重力', '地转偏向力'], 'a': 2, 'e': '太阳辐射提供蒸发能量，重力使降水和径流向低处运动。'}, {'q': '海陆间循环的正确环节顺序是（\u3000）', 'o': ['降水—蒸发—水汽输送—径流', '蒸发—水汽输送—降水—径流', '蒸发—降水—水汽输送—径流', '径流—降水—蒸发—水汽输送'], 'a': 1, 'e': '海陆间循环：蒸发→水汽输送→降水→地表、地下径流回到海洋。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">蒸发、蒸腾</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">水汽输送</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">降水</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">径流回海</text></svg>'}, {'q': '使陆地淡水资源不断补充和更新，最重要的水循环类型是（\u3000）', 'o': ['海上内循环', '陆地内循环', '海陆间循环', '生物水循环'], 'a': 2, 'e': '海陆间循环把海洋水汽输送到陆地，是陆地淡水更新的主要来源。'}, {'q': '下列水循环类型中，参与水体量最大的是（\u3000）', 'o': ['海陆间循环', '陆地内循环', '海上内循环', '内陆水循环'], 'a': 2, 'e': '海洋面积广大，海上内循环参与的水量最大。'}, {'q': '修建水库主要影响水循环的哪一环节（\u3000）', 'o': ['蒸发', '水汽输送', '径流的季节分配', '降水'], 'a': 2, 'e': '水库蓄洪补枯，主要调节地表径流的时间（季节）分配。'}, {'q': '城市地面大面积硬化后，可能出现的变化是（\u3000）', 'o': ['下渗增加，地表径流减少', '下渗减少，地表径流增加', '蒸发显著增强', '降水量明显减少'], 'a': 1, 'e': '地面硬化使下渗减少、地表径流增加，暴雨时易发生城市内涝。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">硬化地面增多</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">下渗减少</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">地表径流增多</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">内涝风险增大</text></svg>'}, {'q': '我国东部季风区河流最主要的补给类型是（\u3000）', 'o': ['雨水补给', '冰川融水补给', '季节性积雪融水补给', '地下水补给'], 'a': 0, 'e': '东部季风区降水丰富，河流水以雨水补给为主，夏汛明显。'}, {'q': '关于水循环的地理意义，说法错误的是（\u3000）', 'o': ['维持全球水的动态平衡', '更新陆地水资源', '塑造地表形态', '使地球上的总水量不断增加'], 'a': 3, 'e': '水循环维持全球水量动态平衡，但并不会使总水量增加。'}], 'quiz_adv': [{'q': '水循环能够发生的根本自然条件是（\u3000）', 'o': ['海水不断运动', '水能在常温常压下发生三态转化', '陆地起伏不平', '大气环流长期存在'], 'a': 1, 'e': '水的固、液、气三态可以相互转化，是水循环发生的内因。'}, {'q': '过度抽取地下水可能带来的问题是（\u3000）', 'o': ['地下水位下降、地面沉降', '降水量显著增加', '河流含沙量减小', '冰川面积扩大'], 'a': 0, 'e': '超采地下水会造成地下水位下降、漏斗区扩大和地面沉降，沿海地区还可能出现海水倒灌。'}, {'q': '跨流域调水主要改变的是（\u3000）', 'o': ['水循环的类型', '水资源的空间分布', '水资源的季节分配', '全球降水量'], 'a': 1, 'e': '调水把水从丰水区送到缺水区，改变的是水资源的空间分布；调节季节分配主要靠水库。'}, {'q': '某闭合流域多年平均水量平衡，正确的表达式是（\u3000）', 'o': ['降水量 = 蒸发量 + 径流量', '降水量 = 蒸发量 - 径流量', '径流量 = 蒸发量 + 降水量', '蒸发量 = 径流量 + 降水量'], 'a': 0, 'e': '流域多年平均意义上，降水量大致等于蒸发量与流出径流量之和。'}, {'q': '山区植被遭到破坏后，对水循环最直接的影响是（\u3000）', 'o': ['下渗减少、地表径流增加、含沙量增大', '降水量增大、径流减小', '地下水位上升', '蒸发量减少为零'], 'a': 0, 'e': '植被破坏使涵养水源能力下降，下渗减少、地表径流增加、水土流失加重。'}, {'q': '以冰川融水补给为主的河流，其径流量的特点是（\u3000）', 'o': ['春季最大', '夏季最大、冬季断流', '全年均匀', '秋季最大'], 'a': 1, 'e': '冰川融水受气温控制，夏季气温最高融水量最大，冬季常断流。'}, {'q': '我国东北山区的河流常在春季形成春汛，其主要补给来源是（\u3000）', 'o': ['雨水', '季节性积雪融水', '冰川融水', '深层地下水'], 'a': 1, 'e': '东北冬季积雪厚，春季气温回升积雪融化，形成春汛。'}, {'q': '建设海绵城市对水循环的主要作用是（\u3000）', 'o': ['增加蒸发、减少降水', '增加下渗、削减洪峰径流', '阻断地表径流', '使地下水不再更新'], 'a': 1, 'e': '海绵城市通过透水铺装、绿地湿地等增加下渗，削减洪峰并回补地下水。'}, {'q': '下列现象中，主要由流水（地表径流）塑造形成的是（\u3000）', 'o': ['内陆沙丘', '河流三角洲', '火山锥', '冰川角峰'], 'a': 1, 'e': '河流携带泥沙在入海口、入湖口堆积形成三角洲，是径流塑造地貌的典型。'}, {'q': '若全球气候变暖加剧，水循环可能发生的变化是（\u3000）', 'o': ['蒸发减弱、降水减少', '蒸发加剧、极端降水事件增多', '水循环完全停止', '海洋水全部转为淡水'], 'a': 1, 'e': '气候变暖使蒸发加剧，水循环更加活跃，极端强降水事件趋于增多。'}]}, {'id': 'g8', 'no': '3.2', 'subject': '地理', 'title': '海水的性质', 'subtitle': '海水的温度、盐度与密度', 'color': '#2a7ab8', 'points': [{'head': '① 海水温度的变化规律', 'body': '海水热量的主要收入是<b>太阳辐射</b>，支出主要是海水<b>蒸发</b>。水平方向上，海水温度<b>由低纬向高纬递减</b>；同一海区<b>夏季水温高、冬季水温低</b>；垂直方向上，水温随深度增加而<b>降低</b>，约 1000 米以下水温很低且变化很小。', 'tip': '三条规律：由低纬向高纬递减、夏高冬低、随深度递减。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">低纬度海区→太阳辐射强→水温高</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">高纬度海区→太阳辐射弱→水温低</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">深层1000米以下→水温低且稳定</text></svg>'}, {'head': '② 影响海水温度的因素', 'body': '主要因素有：<b>纬度</b>（决定太阳辐射强弱）、<b>季节</b>、海水<b>深度</b>、<b>洋流</b>（暖流经过水温偏高，寒流经过水温偏低），此外还有海陆分布、气象条件等。', 'tip': '同纬度海区比较水温，第一步看洋流：暖流增温、寒流降温。'}, {'head': '③ 海水温度的影响', 'body': '① 影响海洋<b>生物</b>的分布与洄游，鱼类随水温变化而迁徙；② 影响<b>航运</b>，高纬度海区冬季结冰，通航期短；③ 影响<b>气候</b>，海水比热容大，沿海地区气温<b>日较差、年较差小</b>，起到调节气温的作用。', 'tip': '沿海气候温和湿润的重要原因：海水比热容大、升降温慢。'}, {'head': '④ 海水盐度的概念', 'body': '<b>盐度</b>表示海水中盐类物质的质量分数，即 1000 克海水中所含<b>溶解盐类物质的总克数</b>，单位为‰。世界大洋平均盐度约为 <b>35‰</b>。海水中主要盐类是<b>氯化钠</b>（味咸）和<b>氯化镁</b>（味苦），所以海水又咸又苦。', 'tip': '平均盐度约 35‰，单位用千分号，别写成百分号。'}, {'head': '⑤ 盐度的水平分布规律', 'body': '全球表层海水盐度<b>由副热带海区向南北两侧递减</b>，呈马鞍形分布。<b>红海</b>盐度最高（约 41‰，因蒸发远大于降水、径流注入极少且海域封闭）；<b>波罗的海</b>盐度最低（约 10‰，因降水较多、蒸发较弱且径流注入多）。', 'tip': '口诀：副热带最高，向两侧递减；红海最咸，波罗的海最淡。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="196" cy="98" r="4.5" fill="#2a7ab8"/><text x="196" y="90" font-size="9.5" fill="#5a5147" text-anchor="middle">红海</text><circle cx="130" cy="58" r="4.5" fill="#2a7ab8"/><text x="130" y="50" font-size="9.5" fill="#5a5147" text-anchor="middle">副热带</text><circle cx="166" cy="29" r="4.5" fill="#2a7ab8"/><text x="166" y="21" font-size="9.5" fill="#5a5147" text-anchor="middle">波罗的海</text><circle cx="94" cy="93" r="4.5" fill="#2a7ab8"/><text x="94" y="85" font-size="9.5" fill="#5a5147" text-anchor="middle">赤道海域</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">表层盐度：副热带高，向南北两侧递减</text></svg>'}, {'head': '⑥ 影响盐度的因素', 'body': '① <b>降水量与蒸发量的对比</b>——最主导因素，蒸发大于降水则盐度高，反之则低；② <b>径流注入</b>，大河入海口盐度偏低；③ <b>洋流</b>，暖流盐度偏高、寒流盐度偏低；④ 海域<b>封闭程度</b>；⑤ <b>结冰与融冰</b>，结冰使盐度升高、融冰使盐度降低。', 'tip': '分析顺序：先看蒸发与降水对比，再看径流、洋流与封闭程度。'}, {'head': '⑦ 海水的密度', 'body': '<b>密度</b>指单位体积内海水的质量。海水密度与<b>温度呈负相关</b>（水温越高密度越小）、与<b>盐度呈正相关</b>（盐度越高密度越大）、随<b>深度和压力增大而增大</b>。', 'tip': '三者关系一句话：低温、高盐、深水的海水密度最大。'}, {'head': '⑧ 密度的分布与影响', 'body': '水平方向：表层海水密度<b>由赤道向两极增大</b>；垂直方向：随深度增加而<b>增大</b>。密度差异大的相邻海区会形成<b>密度流</b>，如直布罗陀海峡表层海水由大西洋流入地中海。海水密度跃层还会使潜艇遭遇<b>海中断崖</b>，威胁航行安全。', 'tip': '典型例子：直布罗陀海峡密度流——表层大西洋流入地中海。'}], 'videos': [{'name': '《蓝色星球》海洋篇', 'type': '纪录片', 'level': '必看', 'kw': '蓝色星球 纪录片 海洋', 'note': '感受大洋环境与海洋生物的分布', 'seg': '看第 1 集 25 分钟', 'covers': '①③', 'minutes': 25}, {'name': '海水为什么又咸又苦', 'type': '科普视频', 'level': '必看', 'kw': '海水 盐度 咸味 原因 科普', 'note': '理解盐度概念与盐度分布的影响因素', 'seg': '10 分钟', 'covers': '④⑤⑥', 'minutes': 10}, {'name': '死海与海水密度科普', 'type': '科普视频', 'level': '补充', 'kw': '死海 海水密度 浮力 科普', 'note': '直观理解盐度、密度与浮力大小的关系', 'seg': '8 分钟', 'covers': '⑦⑧', 'minutes': 8}], 'quiz': [{'q': '表层海水温度的水平分布规律是（\u3000）', 'o': ['由低纬向高纬递减', '由高纬向低纬递减', '与纬度无关', '赤道最低、两极最高'], 'a': 0, 'e': '太阳辐射由低纬向高纬减少，表层水温也随之由低纬向高纬递减。', 'svg': '<svg viewBox="0 0 320 82" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">低纬→太阳辐射强→水温高</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">高纬→太阳辐射弱→水温低</text></svg>'}, {'q': '同一海区，垂直方向上水温的变化是（\u3000）', 'o': ['随深度增加而升高', '随深度增加而降低', '不随深度变化', '先升后降'], 'a': 1, 'e': '表层受太阳辐射影响水温高，深层得不到太阳辐射，水温随深度增加而降低。'}, {'q': '世界大洋的平均盐度约为（\u3000）', 'o': ['3.5‰', '35‰', '350‰', '0.35‰'], 'a': 1, 'e': '世界大洋平均盐度约为 35‰，即每 1000 克海水中约有 35 克盐类物质。'}, {'q': '全球表层海水盐度的分布规律是（\u3000）', 'o': ['由赤道向两极递增', '由副热带海区向南北两侧递减', '与各纬度相同', '由两极向赤道递减'], 'a': 1, 'e': '副热带海区蒸发远大于降水，盐度最高；向赤道和两极两侧递减。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="130" cy="58" r="4.5" fill="#2a7ab8"/><text x="130" y="50" font-size="9.5" fill="#5a5147" text-anchor="middle">副热带</text><circle cx="94" cy="93" r="4.5" fill="#2a7ab8"/><text x="94" y="85" font-size="9.5" fill="#5a5147" text-anchor="middle">赤道</text><circle cx="220" cy="125" r="4.5" fill="#2a7ab8"/><text x="220" y="117" font-size="9.5" fill="#5a5147" text-anchor="middle">两极</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">盐度：副热带最高，向两侧递减</text></svg>'}, {'q': '世界海洋中盐度最高的海区是（\u3000）', 'o': ['波罗的海', '红海', '地中海', '北冰洋'], 'a': 1, 'e': '红海蒸发强烈、降水极少、注入径流少且海域封闭，盐度最高，约 41‰。'}, {'q': '波罗的海盐度很低，主要原因是（\u3000）', 'o': ['纬度低、蒸发强', '降水较多、蒸发较弱且径流注入多', '海域封闭且无径流', '位于赤道多雨区'], 'a': 1, 'e': '波罗的海降水较多、蒸发较弱，又有大量径流注入，盐度最低，约 10‰。'}, {'q': '影响海水盐度的最主要因素是（\u3000）', 'o': ['降水量与蒸发量的对比', '洋流方向', '海水颜色', '海洋深度'], 'a': 0, 'e': '蒸发量与降水量的对比决定盐度高低，是最主要的因素。'}, {'q': '关于海水密度与温度的关系，正确的是（\u3000）', 'o': ['水温越高，密度越大', '水温越高，密度越小', '两者无关', '密度恒定不变'], 'a': 1, 'e': '海水密度与温度呈负相关：水温越高，体积膨胀，密度越小。'}, {'q': '直布罗陀海峡表层海水的流向是（\u3000）', 'o': ['由地中海流入大西洋', '由大西洋流入地中海', '常年静止', '随季节完全逆转'], 'a': 1, 'e': '地中海蒸发强、盐度高、密度大、水位较低，表层海水由大西洋流入地中海，属典型密度流。'}, {'q': '下列因素中，使海水密度增大的是（\u3000）', 'o': ['水温升高', '盐度增大', '深度减小', '压力减小'], 'a': 1, 'e': '海水密度与盐度呈正相关，盐度增大（以及水温降低、压力增大）会使密度增大。'}], 'quiz_adv': [{'q': '同纬度的大洋东西两岸水温不同，造成差异的主要因素是（\u3000）', 'o': ['洋流性质不同，暖流增温、寒流降温', '纬度不同', '太阳辐射完全不同', '海陆分布无影响'], 'a': 0, 'e': '同纬度海区太阳辐射相近，水温差异主要由暖流（增温）和寒流（降温）造成。'}, {'q': '沿海地区气温日较差、年较差较小，主要原因是（\u3000）', 'o': ['海水比热容大，升降温慢', '沿海纬度低', '沿海降水少', '沿海海拔高'], 'a': 0, 'e': '海水比热容远大于陆地，增温降温都慢，对沿海气温起显著调节作用。'}, {'q': '赤道附近海区盐度低于副热带海区，主要原因是（\u3000）', 'o': ['赤道降水丰沛，降水量大于蒸发量', '赤道蒸发量极小', '赤道径流注入少', '赤道海域封闭'], 'a': 0, 'e': '赤道受热虽强但降水更丰沛，降水量大于蒸发量，使表层盐度被稀释而低于副热带。'}, {'q': '红海成为世界盐度最高的海域，其原因不包括（\u3000）', 'o': ['副热带高压控制，降水稀少', '气温高，蒸发旺盛', '海域封闭，与外海交换弱', '有大量河流淡水注入'], 'a': 3, 'e': '红海沿岸几乎没有常年河流注入，淡水补给极少，这正是其盐度高的原因之一。'}, {'q': '某海区冬季发生大面积结冰，其表层盐度变化是（\u3000）', 'o': ['升高', '降低', '不变', '先降低后不变'], 'a': 0, 'e': '海水结冰时盐分析出到未结冰的海水中，使表层海水盐度升高，密度也随之增大。'}, {'q': '长江口附近海域盐度较低，主要原因是（\u3000）', 'o': ['蒸发量过大', '有大量径流淡水注入稀释', '纬度较高', '洋流为暖流'], 'a': 1, 'e': '大河入海口有大量淡水注入，对海水起稀释作用，盐度明显偏低。'}, {'q': '关于海水密度与深度的关系，下列说法正确的是（\u3000）', 'o': ['随深度增加而减小', '随深度增加而增大', '与深度无关', '在表层变化最剧烈'], 'a': 1, 'e': '随深度增加，水温降低、压力增大，海水密度总体呈增大趋势。'}, {'q': '潜艇在航行中遭遇海中断崖，与之直接相关的是（\u3000）', 'o': ['表层盐度过低', '海水密度在垂直方向上突然减小', '海水温度突然升高', '洋流流速过快'], 'a': 1, 'e': '当上层海水密度大于下层（密度跃层异常）时，潜艇浮力骤减形成海中断崖。'}, {'q': '同纬度的暖流与寒流相比，通常暖流具有的特点是（\u3000）', 'o': ['水温较高、盐度较高、密度较小', '水温较低、盐度较低', '水温较高但盐度极低', '各项性质完全相同'], 'a': 0, 'e': '暖流来自低纬，水温高、蒸发强使盐度偏高；温度高又使密度相对较小。'}, {'q': '综合分析：在副热带大洋西岸往往形成盐度较高海域，其主要原因是（\u3000）', 'o': ['暖流经过且蒸发大于降水', '寒流经过且降水丰沛', '纬度高、蒸发弱', '径流注入量大'], 'a': 0, 'e': '副热带蒸发远大于降水，大洋西岸又有暖流经过，水温高、蒸发更强，盐度偏高。'}]}, {'id': 'g9', 'no': '3.3', 'subject': '地理', 'title': '海水的运动', 'subtitle': '波浪、潮汐与洋流', 'color': '#3a7fb8', 'points': [{'head': '① 海水运动的三种形式', 'body': '海水运动主要有<b>波浪、潮汐、洋流</b>三种形式。<b>波浪</b>最常见，多由风力形成；<b>潮汐</b>是海水在天体引潮力作用下的周期性涨落，规律性强；<b>洋流</b>是海水常年稳定地沿一定方向做<b>大规模流动</b>，空间尺度最大、影响最深远。', 'tip': '先分清三种形式，再分别掌握成因和影响。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#3a7fb8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#3a7fb8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">波浪</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">风力为主</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">潮汐</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">引潮力</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">洋流</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">大规模流动</text></svg>'}, {'head': '② 波浪', 'body': '波浪中最常见的是<b>风浪</b>，风力越大、风时越长、风区越广，浪越高。海底地震、火山喷发或风暴引起的巨浪称为<b>海啸</b>或<b>风暴潮</b>，常造成灾害。波浪可侵蚀、搬运和堆积泥沙，<b>塑造海岸地貌</b>，影响港口与航运，也可被开发为<b>波浪能</b>。', 'tip': '波浪的两面性：塑造海岸地貌、提供能源，也可能引发灾害。'}, {'head': '③ 潮汐', 'body': '<b>潮汐</b>是海水在<b>月球和太阳的引潮力</b>作用下发生的周期性涨落现象，白天为潮、夜晚为汐。一昼夜通常出现<b>两次涨落</b>。农历初一（朔）和十五（望）前后，日、地、月大致成一线，引潮力叠加形成<b>大潮</b>；初七、八（上弦）和廿二、三（下弦）形成<b>小潮</b>。', 'tip': '大潮看朔望（初一十五），小潮看上下弦。'}, {'head': '④ 潮汐的影响与利用', 'body': '潮汐影响<b>潮间带生态</b>（滩涂养殖紫菜、贝类）；港口和船坞可利用高潮位进出大型船舶；<b>钱塘江大潮</b>的形成与喇叭形河口、天文大潮和夏季盛行的东南风共同作用有关；潮汐还能用于<b>潮汐发电</b>。', 'tip': '钱塘江大潮成因三要点：喇叭形河口 + 天文大潮 + 东南风助涨。'}, {'head': '⑤ 洋流的概念与分类', 'body': '<b>洋流</b>是海洋中的海水常年比较稳定地沿一定方向做大规模的流动。按水温可分为<b>暖流</b>（比流经海区水温高，一般由低纬流向高纬）和<b>寒流</b>（比流经海区水温低，一般由高纬流向低纬）；按成因可分为<b>风海流</b>、<b>密度流</b>和<b>补偿流</b>。', 'tip': '判读寒暖流：看流向的纬度方向，低纬→高纬多为暖流。'}, {'head': '⑥ 洋流的分布规律', 'body': '① 中低纬副热带海区形成<b>反气旋型大洋环流</b>：北半球<b>顺时针</b>、南半球<b>逆时针</b>，大洋西岸为暖流、东岸为寒流；② 中高纬副极地海区形成<b>气旋型大洋环流</b>：北半球<b>逆时针</b>、南半球<b>顺时针</b>，大洋东岸为暖流、西岸为寒流；③ 南纬 40°—60°形成自西向东的<b>西风漂流</b>（寒流性质）；④ 北印度洋形成<b>季风洋流</b>，夏顺冬逆。', 'tip': '口诀：中低纬反气旋、北顺南逆；中高纬气旋、北逆南顺。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">中低纬环流：北半球顺时针</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">中低纬环流：南半球逆时针</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">中高纬环流：北半球逆时针</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">北印度洋：夏顺冬逆</text></svg>'}, {'head': '⑦ 洋流对气候的影响', 'body': '<b>暖流对沿岸气候有增温增湿作用</b>，如北大西洋暖流使西欧温带海洋性气候向北延伸，俄罗斯的<b>摩尔曼斯克</b>成为北极圈内的不冻港；<b>寒流对沿岸气候有降温减湿作用</b>，如秘鲁寒流使南美西海岸的热带沙漠气候一直延伸到赤道附近。', 'tip': '暖流增温增湿、寒流降温减湿——八个字必背。'}, {'head': '⑧ 洋流对生物、航运和污染的影响', 'body': '① <b>渔业</b>：寒暖流交汇处（北海道、纽芬兰、北海渔场）和<b>上升流</b>海区（秘鲁渔场）饵料丰富，形成大渔场；② <b>航运</b>：顺流航行速度快、省时省燃料，逆流反之；寒暖流交汇或多雾海域不利于航行；③ <b>污染</b>：洋流加快污染物净化速度，但同时会<b>扩大污染范围</b>。', 'tip': '洋流对污染是双刃剑：加快净化，但扩大范围。'}], 'videos': [{'name': '《洋流是怎么回事》科普讲解', 'type': '讲解视频', 'level': '必看', 'kw': '洋流 形成 分布规律 高中地理', 'note': '把洋流分布规律和寒暖流判读讲清楚', 'seg': '全片约 15 分钟', 'covers': '①⑤⑥', 'minutes': 15}, {'name': '《钱塘江大潮》科普纪录片', 'type': '纪录片', 'level': '选看', 'kw': '钱塘江大潮 潮汐 成因 纪录片', 'note': '理解潮汐成因、大潮与小潮的差别', 'seg': '15 分钟', 'covers': '②③④', 'minutes': 15}, {'name': '《海洋》中的洋流与渔场片段', 'type': '纪录片', 'level': '补充', 'kw': '洋流 渔场 寒暖流交汇 纪录片', 'note': '看洋流对渔业资源与沿岸气候的影响', 'seg': '20 分钟', 'covers': '⑦⑧', 'minutes': 20}], 'quiz': [{'q': '海水运动的主要形式包括（\u3000）', 'o': ['波浪、潮汐、洋流', '河流、湖泊、地下水', '降水、蒸发、径流', '风、云、雨'], 'a': 0, 'e': '海水运动的三种基本形式：波浪、潮汐和洋流。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#3a7fb8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#3a7fb8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">波浪</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">风力为主</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">潮汐</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">引潮力</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#3a7fb8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#3a7fb8" text-anchor="middle">洋流</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">大规模流动</text></svg>'}, {'q': '潮汐现象产生的主要原因是（\u3000）', 'o': ['风力吹拂海面', '月球和太阳的引潮力', '海底地震', '海水盐度差异'], 'a': 1, 'e': '潮汐是在月球和太阳的引潮力作用下形成的周期性涨落现象。'}, {'q': '农历初一和十五前后，通常形成（\u3000）', 'o': ['大潮', '小潮', '无潮', '风暴潮'], 'a': 0, 'e': '朔、望时日地月大致成一线，引潮力叠加，形成大潮。'}, {'q': '下列洋流中，按其性质属于暖流的是（\u3000）', 'o': ['由低纬流向高纬、比流经海区水温高的洋流', '由低纬流向高纬、比流经海区水温低的洋流', '由高纬流向低纬的洋流', '所有自西向东的洋流'], 'a': 0, 'e': '暖流指比流经海区水温高的洋流，通常由低纬流向高纬。'}, {'q': '中低纬度副热带海区的大洋环流，北半球的方向是（\u3000）', 'o': ['顺时针', '逆时针', '自东向西直线流动', '无规律'], 'a': 0, 'e': '中低纬副热带海区为反气旋型环流，北半球呈顺时针方向流动。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">中低纬：北半球顺时针</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">中低纬：南半球逆时针</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">中高纬：北半球逆时针</text></svg>'}, {'q': '下列关于中低纬度大洋环流的说法，正确的是（\u3000）', 'o': ['大洋西岸为暖流、东岸为寒流', '大洋西岸为寒流、东岸为暖流', '两岸均为暖流', '两岸均为寒流'], 'a': 0, 'e': '中低纬环流中，大洋西岸（大陆东岸）为暖流，大洋东岸（大陆西岸）为寒流。'}, {'q': '暖流对沿岸气候的影响是（\u3000）', 'o': ['增温增湿', '降温减湿', '没有任何影响', '使降水减少'], 'a': 0, 'e': '暖流对沿岸气候起增温增湿作用，寒流则降温减湿。'}, {'q': '摩尔曼斯克成为北极圈内的不冻港，主要原因是（\u3000）', 'o': ['纬度低', '受北大西洋暖流影响，增温作用明显', '沿岸有强烈上升流', '位于寒暖流交汇处'], 'a': 1, 'e': '北大西洋暖流携带暖水北上，使摩尔曼斯克冬季港口不封冻。'}, {'q': '世界著名渔场多分布在寒暖流交汇处及上升流海区，主要原因是（\u3000）', 'o': ['海水较浅', '饵料丰富，吸引鱼类聚集', '海水盐度最高', '风浪最小'], 'a': 1, 'e': '寒暖流交汇或上升流会把深层营养盐类带到表层，浮游生物繁盛，饵料丰富。'}, {'q': '关于洋流对海洋污染的影响，说法正确的是（\u3000）', 'o': ['只加快净化速度，不影响污染范围', '既加快净化速度，又扩大污染范围', '使污染物完全消失', '对污染物没有任何作用'], 'a': 1, 'e': '洋流可以把污染物带走从而加快净化，但同时也会把污染扩散到更大范围。'}], 'quiz_adv': [{'q': '洋流的成因分类中，由盛行风吹拂海面推动海水运动形成的是（\u3000）', 'o': ['风海流', '密度流', '补偿流', '上升流'], 'a': 0, 'e': '盛行风长期吹拂海面带动海水流动形成的是风海流，如西风漂流。'}, {'q': '秘鲁寒流沿岸形成大面积热带沙漠并延伸到赤道附近，体现的是（\u3000）', 'o': ['暖流增温增湿', '寒流降温减湿', '潮汐作用', '波浪侵蚀'], 'a': 1, 'e': '秘鲁寒流使沿岸气温降低、空气稳定少雨，形成沿海热带沙漠气候。'}, {'q': '北印度洋季风洋流的流向特征是（\u3000）', 'o': ['全年顺时针', '全年逆时针', '夏季顺时针、冬季逆时针', '与季节无关'], 'a': 2, 'e': '夏季盛行西南季风，洋流呈顺时针；冬季盛行东北季风，洋流呈逆时针。'}, {'q': '关于中高纬度副极地海区的大洋环流，下列说法正确的是（\u3000）', 'o': ['北半球呈逆时针方向流动', '北半球呈顺时针方向流动', '南半球不存在环流', '与中低纬环流方向完全相同'], 'a': 0, 'e': '中高纬副极地海区为气旋型环流，北半球呈逆时针方向流动。'}, {'q': '南纬 40°—60° 海域的西风漂流，其性质属于（\u3000）', 'o': ['暖流', '寒流', '上升补偿流', '密度流'], 'a': 1, 'e': '西风漂流源于高纬冷水，水温低于流经海区，属寒流性质。'}, {'q': '一艘海轮从低纬驶往高纬，若选择顺洋流航行，其优势是（\u3000）', 'o': ['节省时间与燃料，提高航速', '必定避开所有海雾', '可以缩短航程为零', '不受洋流影响'], 'a': 0, 'e': '顺洋流航行速度快，能节省时间和燃料；逆流则会降低航速。'}, {'q': '寒暖流交汇的海域往往多海雾，其主要原因是（\u3000）', 'o': ['暖海水遇冷海面冷却凝结成雾', '盐度差异过大', '强烈的上升补偿流', '潮汐涨落剧烈'], 'a': 0, 'e': '暖湿气流流经寒冷海面时被冷却，水汽凝结形成平流雾，影响航行。'}, {'q': '下列关于潮汐能开发利用的说法，正确的是（\u3000）', 'o': ['能量单一但分布广，须建在潮差大的海湾或河口', '只能在赤道地区开发', '与潮汐涨落无关', '开发规模与技术难度都很小'], 'a': 0, 'e': '潮汐能需依托潮差大的海湾或河口筑坝发电，对选址条件要求较高。'}, {'q': '纽芬兰渔场曾经是世界著名渔场，其形成条件主要是（\u3000）', 'o': ['位于北大西洋暖流与拉布拉多寒流交汇处', '位于赤道上升流区', '海域完全封闭', '仅有单一暖流经过'], 'a': 0, 'e': '纽芬兰渔场由墨西哥湾暖流（北大西洋暖流）与拉布拉多寒流交汇形成。'}, {'q': '综合分析，洋流对地理环境的影响体现在（\u3000）', 'o': ['仅影响气候', '仅影响航运', '影响气候、渔业资源、航运和污染物扩散等多个方面', '与地理环境无关'], 'a': 2, 'e': '洋流对气候、渔场分布、海上航运以及污染物净化与扩散都有重要影响。'}]}, {'id': 'g10', 'no': '4.1', 'subject': '地理', 'title': '常见地貌类型', 'subtitle': '喀斯特·河流·风沙·海岸·冰川地貌', 'color': '#1f8a8a', 'points': [{'head': '① 地貌的成因：内力与外力', 'body': '地球表面各种形态的总称叫<b>地貌</b>。<b>内力作用</b>（地壳运动、岩浆活动、变质作用）的总趋势是使地表变得<b>高低不平</b>；<b>外力作用</b>（风化、侵蚀、搬运、堆积）的总趋势是削高填低、使地表<b>趋于平缓</b>。今天看到的地貌，正是二者共同作用的结果。', 'tip': '口诀：内力造骨架高低起伏，外力削高填低削平山地。', 'svg': '<svg viewBox="0 0 320 82" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">内力作用：地壳运动、岩浆活动 → 高低不平</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">外力作用：风化、侵蚀、搬运、堆积 → 趋于平缓</text></svg>'}, {'head': '② 喀斯特地貌（岩溶地貌）', 'body': '由<b>可溶性岩石</b>（主要是石灰岩）受水的<b>溶蚀</b>和<b>淀积</b>作用而形成。地表有<b>峰林、峰丛、孤峰、溶蚀洼地、落水洞</b>；地下有<b>溶洞、地下暗河</b>，洞内常见<b>石钟乳、石笋、石柱</b>。我国以<b>云贵高原、广西桂林</b>一带最典型。', 'tip': '条件两条线：岩石可溶、透水；水有溶蚀力、能流动。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">雨水+CO₂形成弱酸性水</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">沿裂隙溶蚀石灰岩（溶蚀）</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">地表：峰林·洼地·落水洞</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#3d5c5c">地下：溶洞·石钟乳·石笋</text></svg>'}, {'head': '③ 河流地貌：侵蚀地貌', 'body': '河流上游落差大、流速快，以<b>溯源侵蚀和下蚀</b>为主，形成深切狭窄的<b>V形谷（峡谷）</b>，常伴有<b>瀑布、跌水</b>。中下游以<b>侧蚀</b>为主，河道弯曲形成<b>河曲</b>：<b>凹岸侵蚀、凸岸堆积</b>，河流不断蛇曲摆动。', 'tip': '判别口诀：上游下蚀成V形谷，中下游侧蚀成曲流；凹冲凸淤。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">上游：下蚀、溯源侵蚀 → V形谷、瀑布</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">中游：侧蚀为主 → 曲流、凹岸侵蚀凸岸堆积</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">地势平缓：河谷展宽、河床摆动</text></svg>'}, {'head': '④ 河流地貌：堆积地貌', 'body': '河流流速减慢时发生堆积：<b>出山口</b>形成<b>冲（洪）积扇</b>；<b>中下游</b>形成宽广的<b>河漫滩平原</b>；<b>入海口</b>形成近似三角形的<b>三角洲</b>。冲积扇<b>扇顶颗粒粗、边缘细</b>，土壤肥沃，常是重要的农业区与聚落选址地。', 'tip': '三处堆积要对应位置：出山口—冲积扇、中下游—河漫滩、河口—三角洲。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#f7fbfb" stroke="#dbeaea" stroke-width="1"/><circle cx="64" cy="58" r="4.5" fill="#1f8a8a"/><text x="64" y="50" font-size="9.5" fill="#5a5147" text-anchor="middle">出山口·冲积扇</text><circle cx="175" cy="90" r="4.5" fill="#1f8a8a"/><text x="175" y="82" font-size="9.5" fill="#5a5147" text-anchor="middle">中下游·河漫滩</text><circle cx="268" cy="125" r="4.5" fill="#1f8a8a"/><text x="268" y="117" font-size="9.5" fill="#5a5147" text-anchor="middle">河口·三角洲</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">河流堆积地貌：扇顶粗、边缘细</text></svg>'}, {'head': '⑤ 风沙地貌（风成地貌）', 'body': '干旱、半干旱地区由<b>风力侵蚀</b>与<b>风力堆积</b>形成。<b>风蚀地貌</b>有风蚀蘑菇、风蚀柱、<b>雅丹</b>（垄槽相间）、风蚀洼地、戈壁；<b>风积地貌</b>以<b>新月形沙丘</b>最典型，其<b>迎风坡缓、背风坡陡</b>，两翼指向下风向，沙丘会随风移动。', 'tip': '看到新月形沙丘就想到：缓坡=迎风坡，据此判断主导风向。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">风力减弱或遇障碍 → 沙粒沉积</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">颗粒按大小分选堆积</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">形成新月形沙丘：迎风坡缓、背风坡陡</text></svg>'}, {'head': '⑥ 海岸地貌', 'body': '由波浪、潮汐等<b>海水动力</b>塑造。基岩海岸以<b>海蚀地貌</b>为主：<b>海蚀崖、海蚀平台、海蚀拱桥、海蚀柱</b>；平缓海岸以<b>海积地貌</b>为主：<b>海滩（沙滩/砾滩）、沙嘴、沙坝、潟湖</b>。海岸地貌随<b>海平面变化</b>与泥沙来源变化而演变。', 'tip': '分两类记：海蚀地貌（崖·洞·拱桥·柱）＋海积地貌（滩·嘴·坝·潟湖）。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#f7fbfb" stroke="#dbeaea" stroke-width="1"/><circle cx="58" cy="61" r="4.5" fill="#1f8a8a"/><text x="58" y="53" font-size="9.5" fill="#5a5147" text-anchor="middle">海蚀崖</text><circle cx="118" cy="93" r="4.5" fill="#1f8a8a"/><text x="118" y="85" font-size="9.5" fill="#5a5147" text-anchor="middle">海蚀拱桥</text><circle cx="208" cy="109" r="4.5" fill="#1f8a8a"/><text x="208" y="101" font-size="9.5" fill="#5a5147" text-anchor="middle">沙滩</text><circle cx="265" cy="74" r="4.5" fill="#1f8a8a"/><text x="265" y="66" font-size="9.5" fill="#5a5147" text-anchor="middle">沙嘴·潟湖</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">海岸地貌：海蚀（硬岩岸）与海积（平缓岸）</text></svg>'}, {'head': '⑦ 冰川地貌', 'body': '高纬高山地区由<b>冰川侵蚀、搬运、堆积</b>形成。冰蚀地貌有<b>冰斗、刃脊、角峰、U形谷（冰蚀谷）、峡湾</b>；冰川消融后堆积形成的<b>冰碛物</b>大小混杂、<b>分选性差、磨圆度差</b>，多形成冰碛丘陵、终碛垄。', 'tip': '对比记忆：冰川谷=宽浅的U形谷，河流谷=深窄的V形谷。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">积雪压实成冰川冰并向下滑动</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">刨蚀、拔蚀 → 冰斗·角峰·刃脊</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">谷底拓宽，形成宽浅的U形谷</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#3d5c5c">冰川消融，冰碛物杂乱堆积</text></svg>'}, {'head': '⑧ 地貌与人类活动', 'body': '地貌影响人类的生产生活：<b>平原</b>利于耕作、交通和城市建设，聚落<b>密集、多呈团块状</b>；<b>山区</b>聚落多分布在<b>河谷、山间盆地</b>等平缓地带，常沿河谷<b>呈条带状</b>延伸；河谷与山口还关系到交通选线、水库坝址选址、滑坡泥石流防治等。', 'tip': '综合题得分点：地形平坦→聚落密集且团块；地形崎岖→聚落稀疏且条带。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">地形类型决定土地利用方式</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">平原：农业·交通·城市密集</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">山区：聚落沿河谷呈条带状分布</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#3d5c5c">工程选址需避开陡坡、断层与滑坡体</text></svg>'}], 'videos': [{'name': '《地貌的形成》系列·喀斯特篇', 'type': '科普视频', 'level': '必看', 'kw': '喀斯特地貌 形成 石灰岩 溶洞 高中地理', 'note': '把溶蚀—淀积这条主线一次看懂', 'seg': '全片约 15 分钟', 'covers': '①②', 'minutes': 15}, {'name': '《航拍中国》贵州 / 云南篇', 'type': '纪录片', 'level': '选看', 'kw': '航拍中国 贵州 云南 峰林 梯田', 'note': '俯瞰峰林、洼地与河谷聚落，直观理解地貌与人类活动', 'seg': '任选 1 集看 20 分钟', 'covers': '②⑧', 'minutes': 20}, {'name': '《地理·中国》河流与雅丹专题', 'type': '纪录片', 'level': '补充', 'kw': '地理中国 雅丹 河流地貌 三角洲 纪录片', 'note': '看河流冲积扇、三角洲与雅丹、新月形沙丘的实景', 'seg': '20 分钟', 'covers': '③④⑤', 'minutes': 20}], 'quiz': [{'q': '使地表趋于平缓的作用是（\u3000）', 'o': ['外力作用', '内力作用', '变质作用', '岩浆活动'], 'a': 0, 'e': '外力作用通过风化、侵蚀、搬运、堆积削高填低，使地表趋于平缓。', 'svg': '<svg viewBox="0 0 320 82" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">内力：地壳运动 → 高低不平</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">外力：侵蚀堆积 → 趋于平缓</text></svg>'}, {'q': '喀斯特地貌发育最主要的岩石条件是（\u3000）', 'o': ['花岗岩广布', '石灰岩等可溶性岩石广布', '砂岩广布', '玄武岩广布'], 'a': 1, 'e': '喀斯特地貌发育在石灰岩等可溶性岩石分布区。'}, {'q': '我国喀斯特地貌最典型的地区是（\u3000）', 'o': ['东北平原', '云贵高原与广西一带', '内蒙古高原', '塔里木盆地'], 'a': 1, 'e': '我国西南的云贵高原、广西桂林一带石灰岩广布、气候湿热，喀斯特地貌最典型。'}, {'q': '下列属于地下喀斯特地貌的是（\u3000）', 'o': ['峰林', '溶洞、石钟乳、石笋', '溶蚀洼地', '孤峰'], 'a': 1, 'e': '溶洞及洞内的石钟乳、石笋、石柱属于地下喀斯特；峰林、洼地、孤峰属于地表喀斯特。'}, {'q': '河流上游常见的河谷形态是（\u3000）', 'o': ['宽阔的U形谷', '深窄的V形谷', '平坦的河漫滩', '河口三角洲'], 'a': 1, 'e': '河流上游落差大、下蚀强，形成深而窄的V形谷（峡谷）。'}, {'q': '河流流出山口后常形成的堆积地貌是（\u3000）', 'o': ['冲（洪）积扇', '河漫滩平原', '三角洲', '沙丘'], 'a': 0, 'e': '河流出山口地势变缓、流速骤减，泥沙堆积形成扇状的冲（洪）积扇。'}, {'q': '在河流入海口形成的地貌通常是（\u3000）', 'o': ['冲积扇', '三角洲', '冰碛丘陵', '海蚀崖'], 'a': 1, 'e': '河流在入海口处流速减慢、加之海水顶托，泥沙堆积形成三角洲。'}, {'q': '新月形沙丘中，坡度较缓的一侧通常是（\u3000）', 'o': ['迎风坡', '背风坡', '随机分布，无规律', '与风向无关的两侧'], 'a': 0, 'e': '新月形沙丘迎风坡平缓、背风坡陡峭，据此可判断主导风向。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">风从缓坡一侧吹来</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">沙粒被搬运越过脊线</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">在陡坡一侧滑落堆积 → 沙丘移动</text></svg>'}, {'q': '下列属于海蚀地貌的是（\u3000）', 'o': ['沙滩和沙嘴', '潟湖和沙坝', '海蚀崖和海蚀柱', '海滩和砾滩'], 'a': 2, 'e': '海蚀崖、海蚀柱、海蚀拱桥属于海蚀地貌；沙滩、沙嘴、沙坝、潟湖属于海积地貌。'}, {'q': '形成宽浅U形谷的主要外力是（\u3000）', 'o': ['流水侵蚀', '风力侵蚀', '冰川侵蚀', '海浪侵蚀'], 'a': 2, 'e': '冰川沿谷地滑动，强烈刨蚀使谷底拓宽加深，形成宽浅的U形谷（冰蚀谷）。'}], 'quiz_adv': [{'q': '在弯曲河道发育过程中，关于凹岸与凸岸的说法正确的是（\u3000）', 'o': ['凹岸侵蚀、凸岸堆积', '凹岸堆积、凸岸侵蚀', '两岸都以堆积为主', '两岸都以侵蚀为主'], 'a': 0, 'e': '河曲处水流偏向凹岸，凹岸受侵蚀、坡陡水深，凸岸流速慢发生堆积。因此码头宜建在凹岸。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">弯道处水流偏向凹岸</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">凹岸侵蚀、岸陡水深</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">凸岸流速小、泥沙堆积</text></svg>'}, {'q': '关于冲积扇沉积物的分选规律，正确的是（\u3000）', 'o': ['扇顶颗粒粗、边缘颗粒细', '扇顶颗粒细、边缘颗粒粗', '全扇区颗粒均匀一致', '与流速无关'], 'a': 0, 'e': '出山口处流速骤减，粗大颗粒先在扇顶沉积，越往扇缘颗粒越细，分选明显。'}, {'q': '雅丹地貌的主导外力作用是（\u3000）', 'o': ['风力侵蚀', '流水侵蚀', '冰川侵蚀', '海浪侵蚀'], 'a': 0, 'e': '雅丹地貌发育在干旱地区的河湖相沉积物上，由长期风力吹蚀和磨蚀形成垄槽相间的形态。'}, {'q': '与流水堆积相比，冰川堆积物的突出特点是（\u3000）', 'o': ['颗粒粗大、分选性好', '大小混杂、分选性差、磨圆度差', '全部为细小的粉砂', '有明显的层理构造'], 'a': 1, 'e': '冰川搬运能力强但无分选，消融后冰碛物大小混杂、棱角分明，分选性和磨圆度都差。'}, {'q': '治理流动沙丘危害的有效措施是（\u3000）', 'o': ['在迎风坡营造防护林并设置草方格沙障', '在背风坡大规模开垦', '把沙丘全部推平即可', '向沙丘大量灌溉海水'], 'a': 0, 'e': '治理流动沙丘应增加地面粗糙度、降低近地面风速，如设置草方格沙障、营造防护林带。'}, {'q': '喀斯特地貌发育的两个基本条件是（\u3000）', 'o': ['岩石可溶且透水，水具有溶蚀力并能流动', '岩石坚硬且气候寒冷', '植被茂密且地形平坦', '纬度低且风力强大'], 'a': 0, 'e': '喀斯特发育需要可溶性、透水的岩石，以及有溶蚀力且能流动的水，湿热气候更有利。'}, {'q': '黄土高原千沟万壑的地表形态，主要成因是（\u3000）', 'o': ['风力堆积', '流水侵蚀', '冰川刨蚀', '海浪冲刷'], 'a': 1, 'e': '黄土由风力堆积而成，但黄土高原千沟万壑的地表形态主要是夏季暴雨的流水侵蚀造成的。'}, {'q': '下列对比中，正确的是（\u3000）', 'o': ['冰川谷宽浅呈U形，河流谷深窄呈V形', '冰川谷深窄呈V形，河流谷宽浅呈U形', '两者形态完全相同', '两者都由风力作用形成'], 'a': 0, 'e': '冰川刨蚀形成宽浅的U形谷，河流下蚀形成深窄的V形谷，这是区分二者的关键标志。'}, {'q': '下列地貌中，全部属于海积地貌的一组是（\u3000）', 'o': ['海滩、沙嘴、潟湖', '海蚀崖、海蚀柱、海蚀拱桥', '海蚀平台、沙坝、海蚀洞', '幽深的峡湾'], 'a': 0, 'e': '海滩、沙嘴、沙坝、潟湖属于海积地貌；海蚀崖、海蚀柱、海蚀拱桥属海蚀地貌。'}, {'q': '地貌对人类活动影响的正确表述是（\u3000）', 'o': ['平原地区聚落密集，多呈团块状', '山区交通线造价低、密度大', '陡坡最适合大规模农耕', '地貌对聚落选址没有影响'], 'a': 0, 'e': '平原地形平坦，利于耕作、交通与建设，聚落密集且多呈团块状；山区聚落稀疏、多沿河谷呈条带状。'}]}, {'id': 'g11', 'no': '4.2', 'subject': '地理', 'title': '地貌的观察', 'subtitle': '观察顺序·高度·坡度·描述方法', 'color': '#2a7ab8', 'points': [{'head': '① 地貌观察的顺序：先整体后局部', 'body': '观察地貌应遵循<b>从整体到局部、从宏观到微观</b>的顺序：先看<b>大地貌</b>（山地、高原、平原、盆地、丘陵五种基本地形），再观察次一级地貌，最后下降到<b>微观地貌形态</b>（坡面、河谷、沙丘等)。', 'tip': '口诀：先大局后细部，先看"是什么地形"再看"长什么样"。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2a7ab8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2a7ab8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第一步</text><text x="80.0" y="70" font-size="9.5" fill="#6b6357" text-anchor="middle">宏观：基本地形</text><text x="80.0" y="82" font-size="9.5" fill="#6b6357" text-anchor="middle">类型</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第二步</text><text x="160.0" y="70" font-size="9.5" fill="#6b6357" text-anchor="middle">中观：次级地貌</text><text x="160.0" y="82" font-size="9.5" fill="#6b6357" text-anchor="middle">组合</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第三步</text><text x="240.0" y="70" font-size="9.5" fill="#6b6357" text-anchor="middle">微观：坡面、河</text><text x="240.0" y="82" font-size="9.5" fill="#6b6357" text-anchor="middle">谷等</text></svg>'}, {'head': '② 观察地点的选择', 'body': '应选择<b>视野开阔</b>的<b>制高点</b>（山顶、山脊、较高的台地等）作为观察点，便于看清地貌的整体轮廓与空间格局。观察时还应<b>变换位置</b>、多视角印证，避免以偏概全。', 'tip': '选点原则：视野开阔、视野不受遮挡，最好能俯瞰目标区域。'}, {'head': '③ 高度：绝对高度与相对高度', 'body': '<b>绝对高度</b>即<b>海拔</b>，是某地高出海平面的垂直距离，用来判断所属地形类型（平原一般低于200米、丘陵200—500米、山地高于500米、高原海拔较高而地面较平坦）。<b>相对高度</b>是两地海拔之差，它更能反映<b>地表的起伏状况</b>。', 'tip': '判读要诀：类型看绝对高度，起伏看相对高度。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">绝对高度（海拔）：判别地形类型</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">相对高度 = 两地海拔之差：判别起伏大小</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">举例：1200米 - 500米 = 700米</text></svg>'}, {'head': '④ 坡度和坡向', 'body': '<b>坡度</b>是地表单元陡缓的程度，可用<b>相对高度与水平距离的比值</b>表示。坡度影响水土流失强度、农业耕作方式与交通选线。<b>坡向</b>指坡面朝向：北半球山地<b>南坡为阳坡</b>（光照充足但蒸发强），<b>迎风坡降水较多</b>、背风坡多焚风效应而较干。', 'tip': '坡度=垂直落差÷水平距离；阳坡光热水条件与阴坡差别大。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#f7fbfb" stroke="#dbeaea" stroke-width="1"/><circle cx="70" cy="66" r="4.5" fill="#2a7ab8"/><text x="70" y="58" font-size="9.5" fill="#5a5147" text-anchor="middle">缓坡</text><circle cx="160" cy="109" r="4.5" fill="#2a7ab8"/><text x="160" y="101" font-size="9.5" fill="#5a5147" text-anchor="middle">陡坡</text><circle cx="250" cy="135" r="4.5" fill="#2a7ab8"/><text x="250" y="127" font-size="9.5" fill="#5a5147" text-anchor="middle">坡底</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">坡度示意：落差越大、水平距离越小，坡度越陡</text></svg>'}, {'head': '⑤ 地貌的形态与空间规模', 'body': '观察还要注意地貌的<b>形状、规模（面积、长度、宽度）和空间分布</b>，如山体的走向、河谷的宽度、沙丘的排列方向与高度等。规模不同，观察所用的工具也不同：规模大的用<b>遥感影像、地形图</b>，规模小的<b>实地测量</b>。', 'tip': '先定性描述形状，再定量描述规模（长度、宽度、高度）。'}, {'head': '⑥ 借助地形图等高线观察', 'body': '<b>等高线地形图</b>是观察地貌的重要工具：<b>等高线越密集，坡度越陡；越稀疏，坡度越缓</b>。据此可判读山峰、山脊、山谷、鞍部、陡崖等部位，并能绘制<b>地形剖面图</b>直观反映起伏状况。', 'tip': '高频考点：等高线疏密↔坡度陡缓；山谷处等高线凸向高处。', 'svg': '<svg viewBox="0 0 320 200" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="144.0" width="256" height="44.0" fill="#eaf6f6" stroke="#2a7ab8" stroke-width="1"/><text x="42" y="170.0" font-size="11.5" font-weight="700" fill="#1c5f5f">山顶</text><text x="284" y="170.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">闭合等高线</text><rect x="34" y="100.0" width="256" height="44.0" fill="#dceeee" stroke="#2a7ab8" stroke-width="1"/><text x="42" y="126.0" font-size="11.5" font-weight="700" fill="#1c5f5f">山脊</text><text x="284" y="126.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">向低处凸出</text><rect x="34" y="56.0" width="256" height="44.0" fill="#cfe6e6" stroke="#2a7ab8" stroke-width="1"/><text x="42" y="82.0" font-size="11.5" font-weight="700" fill="#1c5f5f">山谷</text><text x="284" y="82.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">向高处凸出</text><rect x="34" y="12.0" width="256" height="44.0" fill="#c2dfdf" stroke="#2a7ab8" stroke-width="1"/><text x="42" y="38.0" font-size="11.5" font-weight="700" fill="#1c5f5f">陡崖</text><text x="284" y="38.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">等高线重叠</text><line x1="34" y1="12" x2="34" y2="188" stroke="#2a7ab8" stroke-width="1.6"/></svg>'}, {'head': '⑦ 地貌的描述方法', 'body': '描述一处地貌通常从四方面入手：① <b>地形类型</b>（以什么地形为主）；② <b>地势起伏</b>（海拔高低、起伏大小、哪里高哪里低）；③ <b>分布状况</b>（各类地貌的空间分布与组合）；④ <b>典型地物</b>与成因(如河谷深切、沙丘连绵)。回答要齐全。', 'tip': '答题模板：以××地形为主 + 地势×高×低 + 起伏大小 + 主要地貌分布。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">① 地形类型：以什么地形为主</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">② 地势：海拔高低、起伏大小与倾斜方向</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">③ 分布：各类地貌的空间组合</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#3d5c5c">④ 典型地物与成因简述</text></svg>'}, {'head': '⑧ 野外观察的准备与安全', 'body': '野外观察前应准备<b>地形图（或电子地图）、罗盘、卷尺、记录表、相机</b>等，注意<b>天气变化</b>，避开<b>陡坡、滑坡体、行洪河道、涨潮区域</b>等危险地带，并及时记录<b>位置、时间、形态特征和测量数据</b>。', 'tip': '野外安全第一：避开陡崖、滑坡与洪水风险区，结伴而行并记录数据。'}], 'videos': [{'name': '《等高线地形图的判读》讲解', 'type': '讲解视频', 'level': '必看', 'kw': '等高线地形图 判读 坡度 高中地理', 'note': '把地形部位与坡度判读一次练熟', 'seg': '全片约 15 分钟', 'covers': '③⑥', 'minutes': 15}, {'name': '《野外如何观察地貌》实践指导', 'type': '科普视频', 'level': '选看', 'kw': '地貌的观察 野外观察 高中地理 必修一', 'note': '了解观察顺序、选点与记录方法', 'seg': '12 分钟', 'covers': '①②⑧', 'minutes': 12}, {'name': '无人机航拍地貌判读合集', 'type': '纪录片', 'level': '补充', 'kw': '航拍 地貌判读 沙丘 河谷 海岸', 'note': '用俯瞰视角练习地貌形态与坡度的判断', 'seg': '任选 15 分钟片段', 'covers': '④⑤⑦', 'minutes': 15}], 'quiz': [{'q': '观察地貌的正确顺序一般是（\u3000）', 'o': ['先从整体到局部、从宏观到微观', '先看微小的地貌细节', '只看一种地貌即可', '随意观察，没有顺序'], 'a': 0, 'e': '观察地貌应遵循从整体到局部、从宏观到微观的顺序。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2a7ab8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2a7ab8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第一步</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">宏观：基本地形</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第二步</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">中观：次级地貌</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">第三步</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">微观：坡面河谷</text></svg>'}, {'q': '选择地貌观察地点时，最主要的要求是（\u3000）', 'o': ['靠近居民点', '视野开阔、便于俯瞰目标区', '海拔越低越好', '必须在河谷底部'], 'a': 1, 'e': '应选择视野开阔的制高点，才能看清地貌的整体轮廓与空间格局。'}, {'q': '相对高度指的是（\u3000）', 'o': ['某地高出海平面的垂直距离', '两地海拔之差', '山顶到山脚的水平距离', '等高线之间的距离'], 'a': 1, 'e': '相对高度是两地海拔的差值，能反映地表起伏状况；海拔才是高出海平面的距离。'}, {'q': '甲地海拔1200米，乙地海拔500米，两地的相对高度是（\u3000）', 'o': ['500米', '700米', '1200米', '1700米'], 'a': 1, 'e': '相对高度=两地海拔之差：1200-500=700米。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#3d5c5c">相对高度 = 海拔之差</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#3d5c5c">1200米 - 500米 = 700米</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#f4f9f9" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#3d5c5c">反映该区域的起伏大小</text></svg>'}, {'q': '下列地形与其海拔特征对应正确的是（\u3000）', 'o': ['平原：海拔多在200米以下，地面平坦开阔', '山地：海拔在200米以下', '丘陵：海拔高于500米且起伏很大', '高原：海拔低且起伏剧烈'], 'a': 0, 'e': '平原一般在200米以下且地面平坦；丘陵200—500米；山地高于500米且起伏大。'}, {'q': '在等高线地形图上，等高线越密集表示（\u3000）', 'o': ['坡度越陡', '坡度越缓', '海拔越低', '一定是平原'], 'a': 0, 'e': '等高线越密集说明单位水平距离内高差越大，坡度越陡。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#f7fbfb" stroke="#dbeaea" stroke-width="1"/><circle cx="100" cy="74" r="4.5" fill="#2a7ab8"/><text x="100" y="66" font-size="9.5" fill="#5a5147" text-anchor="middle">密集=陡坡</text><circle cx="220" cy="106" r="4.5" fill="#2a7ab8"/><text x="220" y="98" font-size="9.5" fill="#5a5147" text-anchor="middle">稀疏=缓坡</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">等高线疏密与坡度陡缓</text></svg>'}, {'q': '描述一处地貌时，一般不包括的内容是（\u3000）', 'o': ['地形类型', '地势起伏与倾斜方向', '各类地貌的分布', '当地人口的具体姓名'], 'a': 3, 'e': '地貌描述主要包括地形类型、地势起伏、分布状况和典型地物，不涉及人口姓名。'}, {'q': '下列关于坡度的说法，正确的是（\u3000）', 'o': ['坡度与相对高度无关', '坡度可用相对高度与水平距离的比值表示', '坡度只与海拔有关', '坡度不能定量表示'], 'a': 1, 'e': '坡度=相对高度÷水平距离，落差越大、水平距离越小，坡度越陡。'}, {'q': '在北半球，山地接受太阳辐射较多、蒸发较强烈的一侧通常是（\u3000）', 'o': ['南坡（阳坡）', '北坡（阴坡）', '任意坡向都一样', '只有东坡'], 'a': 0, 'e': '北半球山地南坡为阳坡，获得太阳辐射多，光照足但蒸发强。'}, {'q': '不属于野外观察地貌常用工具的是（\u3000）', 'o': ['地形图或电子地图', '罗盘与卷尺', '相机与记录表', '天文望远镜'], 'a': 3, 'e': '野外观察常用地形图、罗盘、卷尺、相机和记录表，天文望远镜与地貌观察无关。'}], 'quiz_adv': [{'q': '某区域绝对高度不大但相对高度很大，最可能描述的地形是（\u3000）', 'o': ['开阔平原', '深切峡谷（河谷）地区', '平坦高原面', '滨海沙滩'], 'a': 1, 'e': '峡谷地区若周边地面海拔不高而谷底极深，则表现为绝对高度不大但相对高度大。'}, {'q': '关于相对高度与等高线，下列推断正确的是（\u3000）', 'o': ['等高线重叠处相对高度为零', '等高距相同时，两地间等高线条数越多，相对高度越大', '等高线疏密与相对高度无关', '相对高度一定等于等高距'], 'a': 1, 'e': '等高距相同时，跨越等高线条数越多，两地相对高度越大；相对高度范围可用(n-1)d~(n+1)d估算。'}, {'q': '坡度较大的坡面最容易出现的生态环境问题是（\u3000）', 'o': ['水土流失加剧', '地下水位上升', '土壤盐碱化', '冰川消融'], 'a': 0, 'e': '坡度大，坡面径流速度快、冲刷力强，植被破坏后易发生水土流失甚至滑坡。'}, {'q': '关于迎风坡与背风坡，下列分析正确的是（\u3000）', 'o': ['迎风坡降水较多，背风坡气流下沉增温、气候较干', '背风坡降水一定多于迎风坡', '两坡降水完全相同', '迎风坡一定气候干旱'], 'a': 0, 'e': '气流沿迎风坡抬升致雨，越过山顶在背风坡下沉增温，形成焚风效应，气候较干。'}, {'q': '在野外利用地形图判读时，绘制地形剖面图的主要目的是（\u3000）', 'o': ['直观显示沿某条线的地势起伏状况', '统计人口数量', '确定行政边界', '计算降水量'], 'a': 0, 'e': '地形剖面图能直观反映沿剖面线的高度变化与起伏状况，便于分析地形对工程的影响。'}, {'q': '若要在野外准确判断坡度陡缓，除目估外还应（\u3000）', 'o': ['测量两点间的相对高度和水平距离后计算', '只比较两地海拔', '只看植被茂密程度', '只观察岩石颜色'], 'a': 0, 'e': '坡度=相对高度÷水平距离，需同时量出高差和水平距离才能定量。'}, {'q': '山区聚落多分布在河谷和山间盆地，主要原因是（\u3000）', 'o': ['地形较平坦、水源充足、土壤较肥沃', '海拔过高便于避暑', '远离任何水源', '便于发展海洋渔业'], 'a': 0, 'e': '河谷与山间盆地地形相对平坦、有水有土，交通与耕作条件都优于陡坡。'}, {'q': '观察地貌时变换观察位置的原因，最恰当的是（\u3000）', 'o': ['不同位置、不同视角能相互印证，避免以偏概全', '只是为了拍照好看', '没有实际意义', '为了增加步行里程'], 'a': 0, 'e': '变换观察点可从多视角获取信息，相互印证，避免被局部遮挡或假象误导。'}, {'q': '利用遥感影像观察大尺度地貌的优势在于（\u3000）', 'o': ['覆盖范围大、便于从宏观上识别地貌格局', '能直接测量土壤含水量', '能替代所有野外工作', '只能拍摄地面细节'], 'a': 0, 'e': '遥感影像覆盖范围广、获取快，适合从宏观上识别地貌格局，但细节仍需野外核实。'}, {'q': '综合来看，野外观察一处地貌并作出描述的合理流程是（\u3000）', 'o': ['先目测描述再核查数据', '先选点俯瞰确定整体地形→量算高度坡度→观察坡面、河谷等次级形态→记录整理成完整描述', '直接使用他人结论', '只记录照片不必做文字描述'], 'a': 1, 'e': '合理流程：选点俯瞰把握整体→量算高度与坡度→观察次级地貌形态→整理记录形成完整描述。'}]}, {'id': 'g12', 'no': '5.1', 'subject': '地理', 'title': '植被', 'subtitle': '植被类型、环境关系与垂直分异', 'color': '#1f8a8a', 'points': [{'head': '① 植被及其分类', 'body': '自然界成群生长的各种植物的整体称为<b>植被</b>。天然形成的植被叫<b>天然植被</b>，如森林、草原、荒漠；人工栽培和经营管理的植被叫<b>人工植被</b>，如果园、经济林和城市绿地。', 'tip': '判断关键看是否主要由自然形成；农田作物属于人工植被。'}, {'head': '② 森林植被', 'body': '森林一般分布在<b>湿润和半湿润地区</b>，乔木占主体。热带雨林全年高温多雨，树种丰富、垂直结构复杂；常绿阔叶林分布于亚热带湿润区；落叶阔叶林适应温带季节变化；亚寒带针叶林耐寒。', 'tip': '森林类型判断抓住水热条件：热量递减时，叶片通常由阔叶向针叶变化。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="64" cy="125" r="4.5" fill="#1f8a8a"/><text x="64" y="117" font-size="9.5" fill="#5a5147" text-anchor="middle">热带雨林</text><circle cx="124" cy="106" r="4.5" fill="#1f8a8a"/><text x="124" y="98" font-size="9.5" fill="#5a5147" text-anchor="middle">常绿阔叶林</text><circle cx="196" cy="79" r="4.5" fill="#1f8a8a"/><text x="196" y="71" font-size="9.5" fill="#5a5147" text-anchor="middle">落叶阔叶林</text><circle cx="256" cy="50" r="4.5" fill="#1f8a8a"/><text x="256" y="42" font-size="9.5" fill="#5a5147" text-anchor="middle">针叶林</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">由低纬向高纬，热量总体递减</text></svg>'}, {'head': '③ 草原植被', 'body': '草原一般分布在<b>半湿润、半干旱地区</b>，以草本植物为主。热带草原有明显干湿季，湿季草木茂盛、干季草类枯黄；温带草原降水较少且季节变化明显，植物普遍矮小、根系发达。', 'tip': '草原并非完全缺树；水分不足是乔木难以形成连续林冠的重要原因。'}, {'head': '④ 荒漠植被', 'body': '荒漠植被主要分布在<b>干旱地区</b>，植被稀疏，以旱生灌木、半灌木和耐旱草本为主。植物常具有叶片退化、根系发达、茎叶肉质、表皮厚等特征，以减少蒸腾或储存水分。', 'tip': '形态适应要对应功能：小叶或刺状叶减蒸腾，深根或广根利于吸水。'}, {'head': '⑤ 植被与环境相互作用', 'body': '环境为植被提供<b>光、热、水、土壤</b>等条件，决定植被的类型、结构和分布；植被又能涵养水源、保持水土、调节气候、改良土壤并影响生物多样性。植物形态也能指示环境，如旗形树冠可指示盛行风向。', 'tip': '综合题要写双向关系：环境影响植被，植被反过来改造环境。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">气候、地形、土壤等环境条件</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">决定植被类型、结构和分布</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">植被涵养水源、保持水土、调节气候</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">植被反作用于地理环境</text></svg>'}, {'head': '⑥ 植被的水平分布', 'body': '从赤道向两极，随热量减少，天然植被大致由热带森林向温带森林、亚寒带针叶林和苔原更替；在中纬度大陆，从沿海向内陆随水分减少，常出现<b>森林→草原→荒漠</b>的变化。', 'tip': '纬度地带性主要受热量控制；经度地带性主要受水分控制。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1a7474" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1a7474"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">沿海</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">森林</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">过渡区</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">草原</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">内陆</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">荒漠</text></svg>'}, {'head': '⑦ 植被的垂直分异', 'body': '山地随海拔升高，水热条件发生变化，植被呈带状更替，形成<b>垂直植被带</b>。通常从山麓到山顶的变化类似于从当地向较高纬度的水平变化；山麓植被与当地水平地带植被一致。', 'tip': '同一山地判带谱：先看山麓基带，再看海拔、水分和坡向。', 'svg': '<svg viewBox="0 0 320 205" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="147.8" width="256" height="45.2" fill="#eaf6f6" stroke="#176d6d" stroke-width="1"/><text x="42" y="174.4" font-size="11.5" font-weight="700" fill="#1c5f5f">山地森林</text><text x="284" y="174.4" font-size="9.5" fill="#5a7d7d" text-anchor="end">山麓</text><rect x="34" y="102.5" width="256" height="45.2" fill="#dceeee" stroke="#176d6d" stroke-width="1"/><text x="42" y="129.1" font-size="11.5" font-weight="700" fill="#1c5f5f">针阔混交林</text><text x="284" y="129.1" font-size="9.5" fill="#5a7d7d" text-anchor="end">中低海拔</text><rect x="34" y="57.2" width="256" height="45.2" fill="#cfe6e6" stroke="#176d6d" stroke-width="1"/><text x="42" y="83.9" font-size="11.5" font-weight="700" fill="#1c5f5f">针叶林</text><text x="284" y="83.9" font-size="9.5" fill="#5a7d7d" text-anchor="end">中高海拔</text><rect x="34" y="12.0" width="256" height="45.2" fill="#c2dfdf" stroke="#176d6d" stroke-width="1"/><text x="42" y="38.6" font-size="11.5" font-weight="700" fill="#1c5f5f">高山草甸</text><text x="284" y="38.6" font-size="9.5" fill="#5a7d7d" text-anchor="end">近山顶</text><line x1="34" y1="12" x2="34" y2="193" stroke="#176d6d" stroke-width="1.6"/><text x="22" y="102.5" font-size="9.5" fill="#176d6d" text-anchor="middle" transform="rotate(-90 22 102.5)">海拔升高</text></svg>'}, {'head': '⑧ 植被保护与恢复', 'body': '植被破坏会加剧水土流失、土地荒漠化和生物多样性下降。保护天然林草、封山育林、退化草地休牧轮牧、因地制宜恢复乡土植被，可提升生态系统稳定性。', 'tip': '生态建设不能只追求覆盖率，要遵循水热条件并优先选择适生乡土物种。'}], 'videos': [{'name': '《绿色星球》森林篇', 'type': '纪录片', 'level': '必看', 'kw': '绿色星球 森林 植被 纪录片', 'note': '观察森林群落的垂直结构及植物适应', 'seg': '选看森林生态片段 20 分钟', 'covers': '①②⑤', 'minutes': 20}, {'name': '草原与荒漠植被适应', 'type': '科普视频', 'level': '选看', 'kw': '草原 荒漠 植物适应 高中地理', 'note': '比较半干旱与干旱环境中的植物形态', 'seg': '看草原、荒漠对比段落 15 分钟', 'covers': '③④', 'minutes': 15}, {'name': '山地垂直自然带判读', 'type': '讲解视频', 'level': '补充', 'kw': '山地 垂直自然带 植被 高中地理', 'note': '掌握基带、坡向与带谱判读方法', 'seg': '典型例题讲解 12 分钟', 'covers': '⑥⑦', 'minutes': 12}], 'quiz': [{'q': '下列属于天然植被的是（\u3000）', 'o': ['天然针叶林', '水稻田', '城市行道树', '人工果园'], 'a': 0, 'e': '天然针叶林主要由自然过程形成；农田、行道树和果园属于人工植被。'}, {'q': '森林植被一般主要分布在（\u3000）', 'o': ['湿润和半湿润地区', '极端干旱地区', '永久冰雪带', '盐湖中心'], 'a': 0, 'e': '森林生长需要较充足的水分，主要分布在湿润和半湿润地区。'}, {'q': '热带草原植被的季相变化主要表现为（\u3000）', 'o': ['全年常绿且无变化', '湿季繁茂、干季枯黄', '冬季繁茂、夏季枯黄', '全年被冰雪覆盖'], 'a': 1, 'e': '热带草原受干湿季交替影响，湿季草木繁茂，干季草类枯黄。'}, {'q': '荒漠植物叶片退化为刺的主要作用是（\u3000）', 'o': ['增强光合作用', '减少水分蒸腾', '吸引昆虫传粉', '增加土壤肥力'], 'a': 1, 'e': '叶面积减小能降低蒸腾耗水，是植物适应干旱环境的表现。'}, {'q': '在中纬度大陆由沿海向内陆，常见的植被变化是（\u3000）', 'o': ['森林→草原→荒漠', '荒漠→森林→草原', '草原→森林→荒漠', '苔原→针叶林→雨林'], 'a': 0, 'e': '由沿海向内陆水分总体减少，植被常由森林过渡为草原、荒漠。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1f8a8a" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1f8a8a"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">沿海</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">森林</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">半干旱区</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">草原</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">内陆</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">荒漠</text></svg>'}, {'q': '山地植被出现垂直分异的主要原因是（\u3000）', 'o': ['海拔升高导致水热条件变化', '土壤颜色完全相同', '人类活动绝对停止', '经度没有变化'], 'a': 0, 'e': '随海拔升高，气温和水分状况改变，植被因而呈带状更替。'}, {'q': '一座山地的山麓自然植被通常与（\u3000）', 'o': ['山顶冰雪带一致', '当地水平地带植被一致', '所有山地完全一致', '海洋植被一致'], 'a': 1, 'e': '山麓基带一般与山地所在地区的水平地带性植被一致。'}, {'q': '植被涵养水源的主要表现是（\u3000）', 'o': ['截留降水并增加下渗', '阻止一切降水落地', '使河流永久断流', '完全消除蒸发'], 'a': 0, 'e': '林冠、枯枝落叶层和根系可截留降水、增加下渗并调节径流。'}, {'q': '从赤道向两极，影响植被更替的主导因素是（\u3000）', 'o': ['热量', '土壤质地', '人类耕作', '矿产资源'], 'a': 0, 'e': '纬度升高时热量总体减少，是植被纬度地带性变化的主导因素。'}, {'q': '下列植被恢复措施中最符合因地制宜原则的是（\u3000）', 'o': ['干旱区大规模栽种高耗水乔木', '依据当地水热条件选用乡土物种', '所有地区种植同一树种', '清除全部天然灌草'], 'a': 1, 'e': '生态恢复应尊重当地水热条件，优先采用适生乡土物种。'}], 'quiz_adv': [{'q': '某地乔木高大、常绿，群落分层明显，藤本和附生植物丰富。该地最可能属于（\u3000）', 'o': ['热带雨林', '温带草原', '温带荒漠', '高山苔原'], 'a': 0, 'e': '高温多雨环境形成高大常绿、层次复杂且物种丰富的热带雨林。'}, {'q': '温带草原植物普遍矮小且根系发达，主要是为了适应（\u3000）', 'o': ['降水较少且蒸发较强', '全年高温多雨', '长期水淹', '永久冻土完全覆盖'], 'a': 0, 'e': '矮小植株可减小耗水，发达根系有利于从较大范围吸收水分。'}, {'q': '某荒漠植物具有肉质茎、厚角质层和气孔夜间开放等特征，其共同作用是（\u3000）', 'o': ['增加白天蒸腾', '储水并减少水分损失', '降低根系吸水能力', '适应低温多雨'], 'a': 1, 'e': '这些结构和生理特征共同服务于储水、节水，适应干旱环境。'}, {'q': '同一山地阳坡与阴坡植被带高度不同，主要体现了（\u3000）', 'o': ['坡向造成水热条件差异', '地球公转速度差异', '海陆轮廓变化', '岩石年龄差异'], 'a': 0, 'e': '坡向会影响太阳辐射、蒸发和土壤水分，从而改变植被带分布高度。'}, {'q': '一般情况下，山地垂直植被带谱越丰富，往往说明该山地（\u3000）', 'o': ['相对高度大且所处纬度较低', '海拔很低且纬度很高', '地势平坦且干旱', '没有水热变化'], 'a': 0, 'e': '纬度较低、相对高度较大时，山麓到山顶水热差异大，带谱通常更丰富。'}, {'q': '一座山地从山麓常绿阔叶林向上依次出现落叶阔叶林、针叶林和高山草甸，这种变化最类似于（\u3000）', 'o': ['从较低纬向较高纬的植被变化', '从内陆向沿海的水分增加', '从河流上游到下游的流量变化', '从城市中心到郊区的热岛变化'], 'a': 0, 'e': '海拔升高使热量降低，垂直带谱常类似于由低纬向高纬的植被更替。'}, {'q': '过度放牧使草原退化后，最可能出现的连锁变化是（\u3000）', 'o': ['植被盖度下降→风蚀增强→土地荒漠化', '植被盖度上升→土壤更稳定', '地表径流消失→降水增加', '草场生产力持续提高'], 'a': 0, 'e': '过度放牧破坏地表覆盖，土壤裸露后风蚀增强，可能加剧荒漠化。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">过度放牧</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">植被盖度下降、土壤裸露</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">风蚀与水蚀增强</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">草地退化和荒漠化</text></svg>'}, {'q': '森林被大面积砍伐后，河流洪峰可能提前且增大，主要原因是（\u3000）', 'o': ['林冠截留和土壤下渗能力下降', '植物蒸腾增强', '地下水补给一定增加', '坡面径流完全消失'], 'a': 0, 'e': '失去植被后截留、下渗和滞蓄作用减弱，地表径流汇集更快。'}, {'q': '旗形树冠的枝叶主要伸向一侧，可用来判断当地（\u3000）', 'o': ['盛行风方向', '土壤年龄', '河流含沙量', '地下矿产类型'], 'a': 0, 'e': '长期盛行风会使迎风侧枝芽受损，树冠偏向背风侧，可指示盛行风。'}, {'q': '我国西北干旱区生态恢复时保留耐旱灌草而非追求高大密林，主要依据是（\u3000）', 'o': ['水分承载力', '纬度决定一切', '树木没有生态功能', '灌草耗水一定为零'], 'a': 0, 'e': '干旱区水资源有限，恢复目标必须与区域水分承载力相匹配。'}]}, {'id': 'g13', 'no': '5.2', 'subject': '地理', 'title': '土壤', 'subtitle': '土壤组成、剖面特征与形成养护', 'color': '#2a7ab8', 'points': [{'head': '① 土壤的概念与组成', 'body': '土壤是陆地表层具有一定肥力、能够生长植物的疏松表层，由<b>矿物质、有机质、水分和空气</b>组成。矿物质是主体，有机质虽占比通常较小，却是土壤肥力的重要物质基础。', 'tip': '四种组成相互联系；水分过多会挤占空气，影响根系呼吸。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">岩石风化提供矿物质</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">生物残体转化为有机质</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">孔隙中容纳水分和空气</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">形成能够生长植物的土壤</text></svg>'}, {'head': '② 土壤颜色', 'body': '土壤颜色是判断土壤性质的重要外部特征。腐殖质含量高时常呈<b>黑色或深色</b>；氧化铁丰富时可呈红色；强烈淋溶的土层颜色较浅；盐分在表层聚集可出现灰白色盐霜。', 'tip': '颜色只能提供线索，判断土壤性质还要结合气候、植被和剖面。'}, {'head': '③ 土壤质地', 'body': '按矿物颗粒粒径大小，土壤可分为<b>砂土、壤土和黏土</b>。砂土颗粒大、孔隙大，通气透水但保水保肥弱；黏土颗粒细，保水保肥强但通气透水差；壤土比例适中，较适宜耕作。', 'tip': '砂土“漏水漏肥”，黏土“保水但易板结”，壤土性质较均衡。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2f6fb0" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2f6fb0"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#2f6fb0" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#2f6fb0" text-anchor="middle">砂土</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">通气透水强</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#2f6fb0" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#2f6fb0" text-anchor="middle">壤土</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">性状较均衡</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#2f6fb0" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#2f6fb0" text-anchor="middle">黏土</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">保水保肥强</text></svg>'}, {'head': '④ 森林土壤剖面', 'body': '成熟森林土壤从地表向下常见<b>有机层、腐殖质层、淋溶层、淀积层、母质层和母岩层</b>。淋溶层中的可溶性物质随水下移，部分物质在淀积层积聚。', 'tip': '剖面顺序要从上向下记；淋溶是“带走”，淀积是“积聚”。', 'svg': '<svg viewBox="0 0 320 184" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">地表：有机层</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">腐殖质层</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">淋溶层 → 可溶物质下移</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">淀积层 → 物质积聚</text><path d="M160 138 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="146" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="164" font-size="11.5" fill="#4a4238">母质层与母岩层</text></svg>'}, {'head': '⑤ 耕作土壤剖面', 'body': '长期耕作使自然土壤剖面发生变化，常形成<b>耕作层、犁底层和自然土层</b>。耕作层疏松、富含有机质；犁底层因机械挤压较紧实；下部仍保留部分自然土壤特征。', 'tip': '犁底层过于紧实会妨碍水分下渗和根系下扎，需要合理深松。'}, {'head': '⑥ 主要成土因素', 'body': '土壤是<b>成土母质、气候、生物、地貌、时间和人类活动</b>综合作用的产物。母质提供矿物基础；气候控制风化和有机质分解；生物促进有机质积累，是土壤形成中最活跃的因素。', 'tip': '答成土因素题要结合材料分析主导因素，不能只罗列名称。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="64" cy="58" r="4.5" fill="#2a7ab8"/><text x="64" y="50" font-size="9.5" fill="#5a5147" text-anchor="middle">母质</text><circle cx="136" cy="42" r="4.5" fill="#2a7ab8"/><text x="136" y="34" font-size="9.5" fill="#5a5147" text-anchor="middle">气候</text><circle cx="214" cy="58" r="4.5" fill="#2a7ab8"/><text x="214" y="50" font-size="9.5" fill="#5a5147" text-anchor="middle">生物</text><circle cx="94" cy="119" r="4.5" fill="#2a7ab8"/><text x="94" y="111" font-size="9.5" fill="#5a5147" text-anchor="middle">地貌</text><circle cx="175" cy="135" r="4.5" fill="#2a7ab8"/><text x="175" y="127" font-size="9.5" fill="#5a5147" text-anchor="middle">时间</text><circle cx="256" cy="109" r="4.5" fill="#2a7ab8"/><text x="256" y="101" font-size="9.5" fill="#5a5147" text-anchor="middle">人类</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">多种因素共同影响土壤形成</text></svg>'}, {'head': '⑦ 成土过程与地域差异', 'body': '岩石风化形成成土母质，生物参与使有机质积累，水分迁移造成淋溶和淀积，经过较长时间逐步形成土壤。湿热地区风化、淋溶强，有机质分解快；冷湿地区分解慢，较易积累腐殖质；干旱区常发生盐分表聚。', 'tip': '土壤差异要从气候控制的风化、淋溶和有机质分解速度解释。', 'svg': '<svg viewBox="0 0 320 184" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">裸露岩石风化</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">形成疏松成土母质</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">生物定居并积累有机质</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">物质迁移、淋溶与淀积</text><path d="M160 138 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="146" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="164" font-size="11.5" fill="#4a4238">发育成具有层次的土壤</text></svg>'}, {'head': '⑧ 土壤功能与养护', 'body': '土壤为植物生长提供水分、养分、空气和支撑，也是物质循环的重要场所。合理耕作、秸秆还田、增施有机肥、轮作休耕、种植绿肥、保持水土以及盐碱地排灌改良，可维持和提高土壤肥力。', 'tip': '养护措施要对症：板结要深松增施有机质，侵蚀要覆盖护坡，盐碱化要合理排灌。'}], 'videos': [{'name': '一捧土壤里的世界', 'type': '科普视频', 'level': '必看', 'kw': '土壤 组成 矿物质 有机质 科普', 'note': '认识土壤四种组成及其相互关系', 'seg': '看土壤组成与肥力部分 15 分钟', 'covers': '①②③', 'minutes': 15}, {'name': '土壤剖面的秘密', 'type': '讲解视频', 'level': '选看', 'kw': '土壤剖面 淋溶层 淀积层 高中地理', 'note': '按层观察森林土壤和耕作土壤剖面', 'seg': '剖面观察与判读 18 分钟', 'covers': '④⑤', 'minutes': 18}, {'name': '土壤形成与耕地保护', 'type': '纪录片', 'level': '补充', 'kw': '土壤形成 耕地保护 土壤养护', 'note': '理解成土因素和可持续利用措施', 'seg': '选看成土与养护片段 20 分钟', 'covers': '⑥⑦⑧', 'minutes': 20}], 'quiz': [{'q': '土壤的四种基本组成物质是（\u3000）', 'o': ['矿物质、有机质、水分和空气', '岩石、河流、生物和阳光', '氮气、氧气、二氧化碳和水汽', '砂粒、粉粒、黏粒和砾石'], 'a': 0, 'e': '土壤由矿物质、有机质、水分和空气组成。'}, {'q': '土壤肥力的重要物质基础是（\u3000）', 'o': ['有机质', '空气', '母岩体积', '地表坡度'], 'a': 0, 'e': '有机质能提供养分并改善土壤结构，是土壤肥力的重要物质基础。'}, {'q': '与砂土相比，黏土的典型特点是（\u3000）', 'o': ['通气透水强、保肥弱', '保水保肥强、通气透水较差', '颗粒更大、孔隙更大', '完全不能储水'], 'a': 1, 'e': '黏土颗粒细、孔隙小，保水保肥能力强，但通气透水性较差。'}, {'q': '兼具较好通气透水性和保水保肥能力，较适宜耕作的是（\u3000）', 'o': ['砂土', '壤土', '黏土', '裸露母岩'], 'a': 1, 'e': '壤土中不同粒级颗粒比例适中，土壤性状较均衡。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2a7ab8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2a7ab8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">砂土</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">透水强</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">壤土</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">较均衡</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">黏土</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">保水强</text></svg>'}, {'q': '成熟森林土壤剖面中，位于腐殖质层之下且物质被向下带走的层次是（\u3000）', 'o': ['有机层', '淋溶层', '淀积层', '母岩层'], 'a': 1, 'e': '淋溶层中的可溶性物质随下渗水向下迁移，颜色往往较浅。'}, {'q': '物质在土壤剖面中积聚较明显的层次是（\u3000）', 'o': ['淀积层', '有机层', '犁底层', '母岩层'], 'a': 0, 'e': '从上层迁移下来的物质在淀积层相对积聚。'}, {'q': '耕作土壤中，因长期机械挤压而较紧实的是（\u3000）', 'o': ['耕作层', '犁底层', '有机层', '枯枝落叶层'], 'a': 1, 'e': '犁底层位于耕作层之下，常因农具挤压而较为紧实。'}, {'q': '土壤形成过程中最活跃的因素是（\u3000）', 'o': ['生物', '成土母质', '时间', '坡度'], 'a': 0, 'e': '生物通过有机质积累和生物循环参与成土，是最活跃的成土因素。'}, {'q': '土壤矿物质的主要来源是（\u3000）', 'o': ['成土母质', '植物光合作用', '大气降水', '动物呼吸'], 'a': 0, 'e': '岩石风化形成的成土母质为土壤提供矿物质。'}, {'q': '提高土壤有机质含量的合理措施是（\u3000）', 'o': ['秸秆还田和增施有机肥', '长期单一种植且不施肥', '清除全部枯枝落叶', '反复焚烧表土'], 'a': 0, 'e': '秸秆还田和有机肥能补充有机物，改善土壤结构与肥力。'}], 'quiz_adv': [{'q': '黑土颜色较深、肥力较高，主要与哪一过程有关（\u3000）', 'o': ['有机质大量积累', '氧化铁大量富集', '盐分在表层结晶', '母岩完全未风化'], 'a': 0, 'e': '较丰富的腐殖质使土壤呈深色，并能提高土壤肥力。'}, {'q': '湿热地区部分土壤呈红色，主要是因为（\u3000）', 'o': ['氧化铁等物质富集', '腐殖质异常丰富', '盐分结晶覆盖', '石英颗粒全部消失'], 'a': 0, 'e': '湿热环境中化学风化和淋溶强，铁元素氧化后可使土壤呈红色。'}, {'q': '连续强降水后，黏重土壤中的作物容易烂根，主要原因是（\u3000）', 'o': ['孔隙被水充满、空气不足', '土壤有机质立即归零', '矿物质全部流失', '根系光合作用增强'], 'a': 0, 'e': '土壤水分过多会挤占空气，根系缺氧、呼吸受阻，容易烂根。'}, {'q': '山区陡坡土层通常较薄，主要是因为（\u3000）', 'o': ['侵蚀搬运作用强，物质难以积累', '成土母质一定不存在', '降水绝对为零', '生物活动一定最强'], 'a': 0, 'e': '坡度大时流水侵蚀和物质搬运强，土壤物质不易长期积累。'}, {'q': '同一气候区内，低洼积水地与排水良好坡地的土壤性质不同，说明（\u3000）', 'o': ['地貌影响水热再分配和成土过程', '气候对土壤毫无影响', '成土只由时间决定', '所有母质性质完全相同'], 'a': 0, 'e': '地貌通过影响水分、热量和物质迁移，造成局地土壤差异。'}, {'q': '森林土壤剖面中出现明显淋溶层和淀积层，直接动力主要是（\u3000）', 'o': ['下渗水引起的物质迁移', '地球自转', '植物蒸腾停止', '太阳风活动'], 'a': 0, 'e': '降水下渗会溶解、携带物质向下迁移，形成淋溶和淀积。', 'svg': '<svg viewBox="0 0 320 184" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2f6fb0" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">降水下渗</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2f6fb0" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2f6fb0" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">上层可溶物质被带走</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2f6fb0" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2f6fb0" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">形成淋溶层</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2f6fb0" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2f6fb0" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">物质在下层积聚</text><path d="M160 138 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2f6fb0" stroke-width="1.6" fill="none"/><rect x="18" y="146" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2f6fb0" stroke-width="1.2"/><text x="30" y="164" font-size="11.5" fill="#4a4238">形成淀积层</text></svg>'}, {'q': '东北黑土区长期高强度耕作后土层变薄、肥力下降，适宜的治理组合是（\u3000）', 'o': ['秸秆还田、保护性耕作、保持水土', '继续裸地翻耕、移走秸秆', '增加坡面径流', '只施化肥且取消轮作'], 'a': 0, 'e': '秸秆还田补充有机质，保护性耕作和水土保持可减少侵蚀、维持黑土层。'}, {'q': '干旱区不合理灌溉容易引起土壤盐碱化，其过程是（\u3000）', 'o': ['地下水位上升，强蒸发使盐分在表层积聚', '降水淋洗使盐分全部下移', '有机质积累使土壤变黑', '母岩停止风化'], 'a': 0, 'e': '排水不畅时地下水位升高，水分蒸发后盐分留在表层，造成盐碱化。', 'svg': '<svg viewBox="0 0 320 184" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">过量灌溉且排水不畅</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">地下水位上升</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">地表蒸发旺盛</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">盐分随毛管水上移并表聚</text><path d="M160 138 l0 6 m-4 -3 l4 3 l4 -3" stroke="#3a7fb8" stroke-width="1.6" fill="none"/><rect x="18" y="146" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#3a7fb8" stroke-width="1.2"/><text x="30" y="164" font-size="11.5" fill="#4a4238">土壤盐碱化</text></svg>'}, {'q': '冷湿地区有机质较易积累，主要是因为（\u3000）', 'o': ['低温抑制微生物分解', '植物残体从不产生', '淋溶作用完全停止', '土壤中没有空气'], 'a': 0, 'e': '冷湿环境中微生物活动较弱，有机质分解慢，因而较易积累。'}, {'q': '农业生产中轮作、休耕和种植绿肥的共同目的主要是（\u3000）', 'o': ['维持土壤结构与肥力，促进可持续利用', '永久停止土壤形成', '使土壤只含矿物质', '消除所有土壤生物'], 'a': 0, 'e': '这些措施有助于补充养分、改善结构、减轻连作障碍，保护土壤生产力。'}]}, {'id': 'g14', 'no': '6.1', 'subject': '地理', 'title': '气象灾害', 'subtitle': '洪涝、干旱、台风、寒潮', 'color': '#1f8a8a', 'points': [{'head': '① 自然灾害的概念与分类', 'body': '<b>自然灾害</b>是指发生在地球表层系统中，能造成人们生命和财产损失的<b>自然事件</b>。按成因分为<b>气象灾害、地质灾害、海洋灾害、生物灾害</b>四大类。', 'tip': '判断关键：自然变异 + 造成损失，二者缺一不可。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">气象灾害：洪涝·干旱·台风·寒潮</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">地质灾害：地震·滑坡·泥石流</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">海洋灾害：风暴潮·海啸</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">生物灾害：虫灾·鼠灾</text></svg>'}, {'head': '② 洪涝灾害', 'body': '洪涝包括<b>洪水灾害</b>（河流泛滥、山洪暴发）和<b>雨涝灾害</b>（低洼地积水成涝）。形成条件：短时间<b>强降水</b>或连续性降水、地形<b>低洼排水不畅</b>、河道<b>弯曲淤积、泄洪能力弱</b>。', 'tip': '一句话：水太多 + 排不掉 + 蓄不住。我国夏秋季节多发。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">强降水 / 冰雪融水汇集</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">地势低洼、排水不畅</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">河道淤积、泄洪能力弱</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">洪涝成灾</text></svg>'}, {'head': '③ 洪涝的分布', 'body': '世界洪水多发区：<b>季风气候区</b>（亚洲东部、南部）与河流中下游平原。我国以<b>东部季风区</b>最为严重，尤其<b>长江中下游、珠江三角洲、海河流域</b>。', 'tip': '季风气候降水集中、年际变化大，是洪涝频发的气候根源。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="232" cy="39" r="4.5" fill="#1f8a8a"/><text x="232" y="31" font-size="9.5" fill="#5a5147" text-anchor="middle">东北</text><circle cx="196" cy="64" r="4.5" fill="#1f8a8a"/><text x="196" y="56" font-size="9.5" fill="#5a5147" text-anchor="middle">华北</text><circle cx="208" cy="98" r="4.5" fill="#1f8a8a"/><text x="208" y="90" font-size="9.5" fill="#5a5147" text-anchor="middle">长江中下游</text><circle cx="190" cy="128" r="4.5" fill="#1f8a8a"/><text x="190" y="120" font-size="9.5" fill="#5a5147" text-anchor="middle">珠江流域</text><circle cx="76" cy="61" r="4.5" fill="#1f8a8a"/><text x="76" y="53" font-size="9.5" fill="#5a5147" text-anchor="middle">西北干旱</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">我国洪涝主要分布示意（东部季风区）</text></svg>'}, {'head': '④ 干旱灾害', 'body': '<b>干旱</b>是长期降水偏少导致的<b>水分收支不平衡</b>现象；当干旱导致作物减产、人畜饮水困难时，即形成<b>旱灾</b>。特点是<b>持续时间长、影响范围广</b>，属渐进性灾害。', 'tip': '高频易错：干旱≠旱灾，只有造成损失才称灾。我国华北春旱、长江流域伏旱最典型。'}, {'head': '⑤ 台风', 'body': '台风是发生在<b>西北太平洋</b>洋面上、中心附近最大风力达<b>12级及以上</b>的<b>热带气旋</b>。结构分<b>台风眼</b>（气流下沉、天气晴朗）、<b>漩涡风雨区</b>（狂风暴雨）和<b>外围大风区</b>。危害为<b>狂风、暴雨、风暴潮</b>三件套。', 'tip': '功过两分：酿成灾害，但也带来降水缓解长江中下游伏旱。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">外围大风区：风力渐增</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">漩涡风雨区：狂风暴雨</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">台风眼：风平浪静、天气晴朗</text></svg>'}, {'head': '⑥ 寒潮', 'body': '<b>寒潮</b>是强冷空气迅速入侵造成大范围<b>剧烈降温</b>（24小时降温达一定标准），并伴有<b>大风、雨雪、冻害</b>的天气过程。源地：<b>蒙古—西伯利亚</b>地区。多发于<b>秋末、冬季、初春</b>。', 'tip': '寒潮路径：西路、中路、东路三路南下；初春寒潮常造成农作物低温冻害。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1f8a8a" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1f8a8a"/><circle cx="64.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="64.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">源地</text><text x="64.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">蒙古西伯利亚</text><circle cx="128.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="128.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">南下</text><text x="128.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">大风降温</text><circle cx="192.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="192.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">影响</text><text x="192.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">雨雪冻害</text><circle cx="256.0" cy="52" r="5" fill="#fff" stroke="#1f8a8a" stroke-width="2.5"/><text x="256.0" y="39" font-size="11" font-weight="700" fill="#1f8a8a" text-anchor="middle">危害</text><text x="256.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">农牧渔业</text></svg>'}, {'head': '⑦ 我国气象灾害的分布差异', 'body': '<b>东部季风区</b>：南涝北旱、夏秋多台风；<b>西北内陆</b>：干旱为主；<b>青藏高原</b>：低温冻害与雪灾；<b>沿海地区</b>：台风与风暴潮。', 'tip': '记法：季风区水患多、内陆干旱多、高原低温多、沿海台风多。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="196" cy="61" r="4.5" fill="#1f8a8a"/><text x="196" y="53" font-size="9.5" fill="#5a5147" text-anchor="middle">华北春旱</text><circle cx="214" cy="90" r="4.5" fill="#1f8a8a"/><text x="214" y="82" font-size="9.5" fill="#5a5147" text-anchor="middle">江淮伏旱</text><circle cx="232" cy="119" r="4.5" fill="#1f8a8a"/><text x="232" y="111" font-size="9.5" fill="#5a5147" text-anchor="middle">东南台风</text><circle cx="70" cy="64" r="4.5" fill="#1f8a8a"/><text x="70" y="56" font-size="9.5" fill="#5a5147" text-anchor="middle">西北干旱</text><circle cx="64" cy="109" r="4.5" fill="#1f8a8a"/><text x="64" y="101" font-size="9.5" fill="#5a5147" text-anchor="middle">青藏雪灾</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">我国主要气象灾害分布示意</text></svg>'}, {'head': '⑧ 灾害的关联性与灾害链', 'body': '一种自然灾害常诱发或加重另一种灾害，形成<b>灾害链</b>。如暴雨→<b>洪涝</b>→山区<b>滑坡、泥石流</b>→阻断江河形成<b>堰塞湖</b>；干旱→植被枯死→<b>森林火灾</b>。', 'tip': '综合题常考：说出某暴雨过程的次生灾害，按灾害链依次作答。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">强暴雨</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">河谷洪水泛滥</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">山区滑坡泥石流</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">堰塞湖溃决风险</text></svg>'}], 'videos': [{'name': '《洪水与防汛》纪录片', 'type': '纪录片', 'level': '必看', 'kw': '洪水 洪涝灾害 纪录片 中国防汛', 'note': '理解洪涝的成因、分布与防御工程', 'seg': '看 20 分钟', 'covers': '①②③', 'minutes': 20}, {'name': '《台风的形成与防御》科普', 'type': '科普视频', 'level': '必看', 'kw': '台风形成 结构 台风眼 防御 科普', 'note': '看懂台风结构并记住三大危害', 'seg': '12 分钟', 'covers': '⑤', 'minutes': 12}, {'name': '《寒潮来了怎么办》科普', 'type': '科普视频', 'level': '选看', 'kw': '寒潮 冷空气 降温 冻害 科普', 'note': '了解寒潮路径与农牧业防寒措施', 'seg': '10 分钟', 'covers': '⑥⑦', 'minutes': 10}], 'quiz': [{'q': '下列不属于气象灾害的是（\u3000）', 'o': ['洪涝', '干旱', '地震', '寒潮'], 'a': 2, 'e': '地震属于地质灾害，其余三项均由大气过程引起，属气象灾害。'}, {'q': '我国东部季风区洪涝灾害多发的气候原因是（\u3000）', 'o': ['降水集中在夏秋季节且年际变化大', '全年降水均匀', '冬季降水最多', '气温年较差小'], 'a': 0, 'e': '季风气候降水集中且年际变化大，易形成洪涝。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">夏秋降水集中</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">短时间大量来水</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">河湖宣泄不及</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1f8a8a" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1f8a8a" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">洪涝成灾</text></svg>'}, {'q': '下列地区中，洪涝灾害最严重的是（\u3000）', 'o': ['塔里木盆地', '长江中下游平原', '内蒙古高原', '青藏高原'], 'a': 1, 'e': '长江中下游平原地势低平、降水丰沛、河道弯曲，洪涝最严重。'}, {'q': '关于干旱与旱灾的关系，正确的是（\u3000）', 'o': ['干旱就是旱灾', '干旱造成损失后才称为旱灾', '两者毫无关系', '旱灾只发生在沙漠'], 'a': 1, 'e': '干旱是自然现象，造成人员伤亡或财产损失即成旱灾。'}, {'q': '我国华北地区春季易发生干旱，主要原因是（\u3000）', 'o': ['春季气温回升快、蒸发强，而雨季尚未来临', '春季降水最多', '春季河流全部干涸', '春季植被稀少'], 'a': 0, 'e': '华北春季升温快、蒸发旺盛，而夏季风未到、降水少，形成春旱。'}, {'q': '长江中下游地区的伏旱主要出现在（\u3000）', 'o': ['3—4月', '7—8月', '10—11月', '12—2月'], 'a': 1, 'e': '7—8月受副热带高压控制，盛行下沉气流，晴热少雨形成伏旱。'}, {'q': '台风中心（台风眼）的天气状况是（\u3000）', 'o': ['狂风暴雨', '风平浪静、天气晴朗', '持续大雪', '雷暴不断'], 'a': 1, 'e': '台风眼气流下沉，风平浪静、天气晴朗；周围漩涡风雨区才有狂风暴雨。'}, {'q': '台风带来的主要危害不包括（\u3000）', 'o': ['狂风', '暴雨', '风暴潮', '沙尘暴'], 'a': 3, 'e': '台风三大危害是狂风、暴雨、风暴潮；沙尘暴属干旱区灾害。'}, {'q': '影响我国的寒潮主要发源于（\u3000）', 'o': ['太平洋洋面', '蒙古—西伯利亚地区', '印度洋', '赤道海域'], 'a': 1, 'e': '寒潮源自蒙古—西伯利亚高压，冷空气南下形成寒潮。'}, {'q': '寒潮的多发季节是（\u3000）', 'o': ['盛夏', '秋末至初春', '整个雨季', '春季末期到夏季'], 'a': 1, 'e': '我国寒潮多发于秋末、冬季和初春。'}], 'quiz_adv': [{'q': '同一种灾害在不同地区的影响不同，这主要体现自然灾害的（\u3000）', 'o': ['区域性', '周期性', '不可预测性', '单一性'], 'a': 0, 'e': '灾害的时空分布和影响程度存在明显的区域差异。'}, {'q': '某河流域上游植被遭大面积破坏，最可能加重下游的（\u3000）', 'o': ['河流含沙量增大，河道淤积，洪涝加剧', '河流径流量减小，洪涝减轻', '地下水位下降', '台风频率增加'], 'a': 0, 'e': '植被破坏→水土流失→含沙量增大→河道淤积→泄洪能力下降→洪涝加剧。'}, {'q': '围湖造田导致湖区面积缩小，对洪涝的影响是（\u3000）', 'o': ['湖泊调蓄能力下降，洪涝加剧', '湖泊调蓄能力增强，洪涝减轻', '对洪涝没有影响', '使河流径流季节变化消失'], 'a': 0, 'e': '湖泊萎缩使其调蓄洪水的能力下降，加重洪涝威胁。'}, {'q': '城市内涝（看海现象）加剧的主要人为原因是（\u3000）', 'o': ['地面硬化，下渗减少，地表径流迅速汇集', '城市降水显著减少', '城市河道变宽', '城市气温偏低'], 'a': 0, 'e': '不透水地面增加使下渗减少、径流汇集快，排水系统跟不上即成内涝。'}, {'q': '关于台风的功过评价，正确的是（\u3000）', 'o': ['只有危害没有益处', '带来狂风暴雨等灾害，也可缓解南方伏旱', '台风眼区降水最丰沛', '台风只影响沿海地区'], 'a': 1, 'e': '台风既致灾，其降水又能缓解长江中下游伏旱，应辩证看待。'}, {'q': '台风在我国登陆的主要省份，不包括（\u3000）', 'o': ['广东', '福建', '新疆', '海南'], 'a': 2, 'e': '台风登陆我国东南沿海，新疆深居内陆，不受台风影响。'}, {'q': '寒潮给农作物带来的主要危害类型是（\u3000）', 'o': ['低温冻害', '水土流失', '土壤盐碱化', '土地荒漠化'], 'a': 0, 'e': '寒潮剧烈降温造成农作物低温冻害。'}, {'q': '下列现象中，体现自然灾害关联性的是（\u3000）', 'o': ['夏季风不稳定导致降水年际变化大', '暴雨引发山区的滑坡和泥石流', '纬度位置决定热量差异', '洋流影响沿岸气候'], 'a': 1, 'e': '暴雨→滑坡→泥石流构成典型的灾害链，体现灾害的关联性。'}, {'q': '防御台风灾害的工程措施中，最不合理的是（\u3000）', 'o': ['营造沿海防护林', '加固堤防、修建避风港', '在河口大量围垦滩涂', '完善城市排水系统'], 'a': 2, 'e': '围垦滩涂会削弱沿海行洪与缓冲能力，反而加剧台风、风暴潮灾害。'}, {'q': '综合我国气象灾害的时空分布，下列说法正确的是（\u3000）', 'o': ['南涝北旱是基本的空间格局之一', '西北地区洪涝最频繁', '青藏高原台风灾害最严重', '台风主要影响西北内陆'], 'a': 0, 'e': '我国气象灾害基本格局之一是南涝北旱，西北以干旱、青藏以低温雪灾为主。'}]}, {'id': 'g15', 'no': '6.2', 'subject': '地理', 'title': '地质灾害', 'subtitle': '地震、滑坡、泥石流', 'color': '#1d7f7f', 'points': [{'head': '① 地质灾害概述', 'body': '<b>地质灾害</b>是地质动力作用下导致的灾害，主要包括<b>地震、滑坡、泥石流、火山喷发、地面塌陷</b>等，具有<b>突发性强、破坏力大、易形成灾害链</b>的特点。', 'tip': '本节三大主角：地震、滑坡、泥石流。'}, {'head': '② 地震的基本概念', 'body': '岩层<b>断裂错动</b>释放能量产生地震波，引起地面震动即<b>地震</b>。地下震源正上方的地面叫<b>震中</b>；震源到地面的垂直距离叫<b>震源深度</b>；震中到地面的距离叫<b>震中距</b>。', 'tip': '成因=地壳运动使岩层积累的应力突然释放。', 'svg': '<svg viewBox="0 0 320 130" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="82.7" width="256" height="35.3" fill="#eaf6f6" stroke="#1d7f7f" stroke-width="1"/><text x="42" y="104.3" font-size="11.5" font-weight="700" fill="#1c5f5f">震源</text><text x="284" y="104.3" font-size="9.5" fill="#5a7d7d" text-anchor="end">岩层断裂</text><rect x="34" y="47.3" width="256" height="35.3" fill="#dceeee" stroke="#1d7f7f" stroke-width="1"/><text x="42" y="69.0" font-size="11.5" font-weight="700" fill="#1c5f5f">震源深度</text><text x="284" y="69.0" font-size="9.5" fill="#5a7d7d" text-anchor="end">垂直距离</text><rect x="34" y="12.0" width="256" height="35.3" fill="#cfe6e6" stroke="#1d7f7f" stroke-width="1"/><text x="42" y="33.7" font-size="11.5" font-weight="700" fill="#1c5f5f">震中</text><text x="284" y="33.7" font-size="9.5" fill="#5a7d7d" text-anchor="end">地表投影</text><line x1="34" y1="12" x2="34" y2="118" stroke="#1d7f7f" stroke-width="1.6"/><text x="22" y="65.0" font-size="9.5" fill="#1d7f7f" text-anchor="middle" transform="rotate(-90 22 65.0)">自下而上</text></svg>'}, {'head': '③ 震级与烈度', 'body': '<b>震级</b>表示<b>地震释放能量的大小</b>，一次地震<b>只有一个震级</b>；<b>烈度</b>表示<b>地面破坏程度</b>，同一次地震有<b>多个烈度</b>。烈度与震级、震源深度、震中距、地质构造、建筑抗震性能等有关。', 'tip': '必考区分：震级唯一、烈度多个；震级越大烈度一般越大。'}, {'head': '④ 地震的分布', 'body': '世界两大地震带：<b>环太平洋地震带</b>（集中约80%的浅源地震）和<b>地中海—喜马拉雅地震带</b>。它们基本与<b>板块交界处</b>一致。', 'tip': '中国位于两大地震带之间，是多地震国家。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="250" cy="74" r="4.5" fill="#1d7f7f"/><text x="250" y="66" font-size="9.5" fill="#5a5147" text-anchor="middle">环太平洋</text><circle cx="130" cy="93" r="4.5" fill="#1d7f7f"/><text x="130" y="85" font-size="9.5" fill="#5a5147" text-anchor="middle">地中海—喜马拉雅</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">世界两大地震带示意</text></svg>'}, {'head': '⑤ 滑坡', 'body': '<b>滑坡</b>是山地斜坡上的岩体或土体，在<b>重力</b>作用下沿一定的<b>滑动面</b>整体下滑的现象。诱发因素：<b>降水（暴雨）下渗</b>、地震、河流冲刷坡脚、<b>人类工程活动</b>（开挖坡脚、堆放弃土）。', 'tip': '滑坡三要素：岩土体 + 滑动面 + 重力驱动。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">岩体破碎、坡陡</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">暴雨下渗、润滑滑面</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">地震或人为扰动</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">整体下滑成灾</text></svg>'}, {'head': '⑥ 泥石流', 'body': '<b>泥石流</b>是山区<b>沟谷</b>中由<b>暴雨、冰雪融水</b>等激发的、含大量<b>泥沙石块</b>的<b>特殊洪流</b>。形成三条件：<b>地形陡峻、松散物质丰富、短时有大量水流</b>。', 'tip': '破坏方式：淤埋、冲毁、堵塞河道形成堰塞湖。'}, {'head': '⑦ 滑坡与泥石流的比较', 'body': '相同点：都发生在<b>山区</b>、都由<b>重力+水</b>诱发、都具有<b>突发性</b>。不同点：滑坡是<b>斜坡整体下滑</b>，物质较干；泥石流是<b>沟谷中的洪流</b>，含大量水与泥沙，流动性更强。', 'tip': '判别关键：滑坡看坡体，泥石流看沟谷流水。'}, {'head': '⑧ 我国地质灾害多发的原因', 'body': '① 地处<b>两大地震带交汇</b>处，地壳活动强烈；② <b>地形复杂、山地众多</b>，地势起伏大；③ <b>季风气候</b>降水集中，多暴雨；④ 人类活动（采矿、修路、滥伐）破坏地表稳定。此外地质灾害常形成灾害链：<b>地震→滑坡→泥石流→堰塞湖</b>。', 'tip': '分析模板：地质 + 地形 + 气候 + 人类活动。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1d7f7f" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1d7f7f"/><circle cx="64.0" cy="52" r="5" fill="#fff" stroke="#1d7f7f" stroke-width="2.5"/><text x="64.0" y="39" font-size="11" font-weight="700" fill="#1d7f7f" text-anchor="middle">板块运动</text><text x="64.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">地震</text><circle cx="128.0" cy="52" r="5" fill="#fff" stroke="#1d7f7f" stroke-width="2.5"/><text x="128.0" y="39" font-size="11" font-weight="700" fill="#1d7f7f" text-anchor="middle">山体破碎</text><text x="128.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">滑坡堵江</text><circle cx="192.0" cy="52" r="5" fill="#fff" stroke="#1d7f7f" stroke-width="2.5"/><text x="192.0" y="39" font-size="11" font-weight="700" fill="#1d7f7f" text-anchor="middle">堰塞湖</text><text x="192.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">溃决风险</text><circle cx="256.0" cy="52" r="5" fill="#fff" stroke="#1d7f7f" stroke-width="2.5"/><text x="256.0" y="39" font-size="11" font-weight="700" fill="#1d7f7f" text-anchor="middle">暴雨激发</text><text x="256.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">泥石流</text></svg>'}], 'videos': [{'name': '《汶川地震十周年》纪录片', 'type': '纪录片', 'level': '必看', 'kw': '汶川地震 纪录片 地震成因', 'note': '理解地震成因、震级烈度与灾害链', 'seg': '看 25 分钟', 'covers': '②③④⑧', 'minutes': 25}, {'name': '《滑坡与泥石流》科普', 'type': '科普视频', 'level': '必看', 'kw': '滑坡 泥石流 成因 区别 科普', 'note': '通过实拍画面区分滑坡与泥石流', 'seg': '12 分钟', 'covers': '⑤⑥⑦', 'minutes': 12}, {'name': '《板块运动与地震带》讲解', 'type': '讲解视频', 'level': '选看', 'kw': '板块运动 环太平洋地震带 高中地理', 'note': '把地震带分布与板块边界对应起来', 'seg': '15 分钟', 'covers': '④', 'minutes': 15}], 'quiz': [{'q': '下列关于震级和烈度的说法，正确的是（\u3000）', 'o': ['一次地震只有一个震级，但有多个烈度', '一次地震有多个震级，只有一个烈度', '震级和烈度完全相同', '震级表示地面破坏程度'], 'a': 0, 'e': '震级表示释放能量大小，一次地震只有一个；烈度表示破坏程度，各地不同。', 'svg': '<svg viewBox="0 0 320 110" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="34" y="55.0" width="256" height="43.0" fill="#eaf6f6" stroke="#1d7f7f" stroke-width="1"/><text x="42" y="80.5" font-size="11.5" font-weight="700" fill="#1c5f5f">震源</text><text x="284" y="80.5" font-size="9.5" fill="#5a7d7d" text-anchor="end">释能</text><rect x="34" y="12.0" width="256" height="43.0" fill="#dceeee" stroke="#1d7f7f" stroke-width="1"/><text x="42" y="37.5" font-size="11.5" font-weight="700" fill="#1c5f5f">震中</text><text x="284" y="37.5" font-size="9.5" fill="#5a7d7d" text-anchor="end">地表</text><line x1="34" y1="12" x2="34" y2="98" stroke="#1d7f7f" stroke-width="1.6"/><text x="22" y="55.0" font-size="9.5" fill="#1d7f7f" text-anchor="middle" transform="rotate(-90 22 55.0)">自下而上</text></svg>'}, {'q': '表示地震释放能量大小的指标是（\u3000）', 'o': ['震级', '烈度', '震源深度', '震中距'], 'a': 0, 'e': '震级表示地震释放能量的大小。'}, {'q': '下列因素中，不影响某地震中以外地区烈度的是（\u3000）', 'o': ['震源深度', '震中距', '当地建筑抗震性能', '震源的命名方式'], 'a': 3, 'e': '烈度与震级、震源深度、震中距、地质构造与建筑性能有关，与命名无关。'}, {'q': '世界两大地震带是（\u3000）', 'o': ['环太平洋地震带和地中海—喜马拉雅地震带', '大西洋地震带与北冰洋地震带', '赤道地震带与温带地震带', '南极地震带与欧亚地震带'], 'a': 0, 'e': '世界地震集中分布在环太平洋地震带和地中海—喜马拉雅地震带。', 'svg': '<svg viewBox="0 0 320 180" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="10" y="10" width="300" height="160" rx="10" fill="#faf7f2" stroke="#e3dbcf" stroke-width="1"/><circle cx="244" cy="74" r="4.5" fill="#1d7f7f"/><text x="244" y="66" font-size="9.5" fill="#5a5147" text-anchor="middle">环太平洋</text><circle cx="130" cy="90" r="4.5" fill="#1d7f7f"/><text x="130" y="82" font-size="9.5" fill="#5a5147" text-anchor="middle">地中海—喜马拉雅</text><text x="160" y="174" font-size="9" fill="#9a9086" text-anchor="middle">两大地震带示意</text></svg>'}, {'q': '地震的形成原因是（\u3000）', 'o': ['岩层断裂错动，能量突然释放', '台风带来大风', '河流长期侵蚀', '植被大量减少'], 'a': 0, 'e': '地壳运动使岩层变形积累能量，超过岩石承受限度时断裂错动，形成地震。'}, {'q': '滑坡发生的关键条件是（\u3000）', 'o': ['岩体沿滑动面整体下滑', '河水水量突然增大', '地层大面积沉降', '沿海海面上升'], 'a': 0, 'e': '滑坡是斜坡上的岩体或土体沿滑动面整体下滑的现象。'}, {'q': '泥石流的物质组成特点是（\u3000）', 'o': ['含大量泥沙、石块的特殊洪流', '全部是干燥的沙土', '仅有岩石碎块', '由积雪构成'], 'a': 0, 'e': '泥石流是含有大量泥沙石块的特殊洪流。'}, {'q': '泥石流形成必须具备的三个条件是（\u3000）', 'o': ['地形陡峻、松散物质丰富、短时大量水流', '低温、积雪厚、风力强', '平原广布、降水均匀、植被茂密', '高温、干旱、蒸发强'], 'a': 0, 'e': '陡峻地形 + 丰富松散物质 + 短时大量水流，是泥石流三要素。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">地形陡峻</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">松散物质丰富</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">短时暴雨</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1d7f7f" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1d7f7f" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">泥石流暴发</text></svg>'}, {'q': '滑坡与泥石流的共同点是（\u3000）', 'o': ['都发生在山区，都与重力和水有关', '都发生在平原地区', '都由火山喷发引起', '都属于气象灾害'], 'a': 0, 'e': '二者均发生在山区，均受重力作用并常由暴雨诱发。'}, {'q': '下列人类活动中，最可能诱发滑坡的是（\u3000）', 'o': ['开挖坡脚、在陡坡上堆放弃土', '在平原区植树造林', '修建水库大坝泄洪', '在草原适度放牧'], 'a': 0, 'e': '开挖坡脚或堆放弃土破坏斜坡稳定，是常见的人为诱发因素。'}], 'quiz_adv': [{'q': '同一次地震中，震中距越远，通常烈度（\u3000）', 'o': ['越小', '越大', '保持不变', '先增后减'], 'a': 0, 'e': '震中距越大，地震波能量衰减越多，烈度一般越小。'}, {'q': '同一次地震中，震源深度越浅，则震中地区（\u3000）', 'o': ['烈度一般越大', '烈度越小', '震级变大', '震级变小'], 'a': 0, 'e': '震源越浅，能量到达地表衰减少，震中区烈度一般越大。'}, {'q': '我国西南地区地震、滑坡、泥石流多发，其共同的自然基础是（\u3000）', 'o': ['地处板块交界、山高谷深、降水集中', '平原广阔、地下水位高', '气候干旱、植被稀少', '纬度低、气温高'], 'a': 0, 'e': '西南地区地壳活跃、地形起伏大、暴雨集中，故三类灾害都多发。'}, {'q': '山区沟谷中突发泥流并携带巨大石块，其灾害类型应判定为（\u3000）', 'o': ['泥石流', '滑坡', '地震', '火山喷发'], 'a': 0, 'e': '沟谷中含大量泥沙石块的洪流是泥石流的典型特征。'}, {'q': '水库蓄水后库区滑坡增多，主要原因是（\u3000）', 'o': ['水位变动改变坡体水文地质条件并软化滑动面', '水库使地壳运动加剧', '水库使降水明显减少', '库区岩层全部溶解'], 'a': 0, 'e': '库水位涨落使坡体浸水、孔隙水压变化、滑动面软化，易诱发滑坡。'}, {'q': '地震后在山区常出现滑坡、泥石流增多，这说明自然灾害具有（\u3000）', 'o': ['关联性与灾害链特征', '周期性', '不可预防性', '区域独立性'], 'a': 0, 'e': '地震使山体破碎松动，遇暴雨易发生滑坡泥石流，形成灾害链。'}, {'q': '堰塞湖的形成过程是（\u3000）', 'o': ['滑坡或泥石流堵塞河道，水位抬升成湖', '河流改道自然形成', '人工修筑大坝形成', '冰川消融积水形成'], 'a': 0, 'e': '地震滑坡体堵塞河谷，河水壅高形成堰塞湖，溃决风险大。'}, {'q': '在同等暴雨条件下，下列哪类山坡最易发生滑坡（\u3000）', 'o': ['岩层破碎、坡面陡且与岩层层面倾向一致的坡', '植被茂密、坡度平缓的坡', '基岩完整、坡面平缓的坡', '石灰岩分布的缓坡'], 'a': 0, 'e': '岩层破碎、坡度陡且顺层（层面与坡向一致）的斜坡稳定性最差。'}, {'q': '我国东部沿海地区相对西南山区，地质灾害较少的主要原因是（\u3000）', 'o': ['地壳相对稳定且地形起伏较小', '降水更少', '人口稀少', '植被更好'], 'a': 0, 'e': '东部沿海地壳较稳定、地形以平原丘陵为主，地质灾害相对较少。'}, {'q': '综合防御山区地质灾害，最有效的做法是（\u3000）', 'o': ['加强监测预警 + 工程治理 + 避让搬迁 + 恢复植被的组合措施', '只依靠工程加固', '只依赖天气预报', '全部居民迁出所有山区'], 'a': 0, 'e': '地质灾害防治需监测、工程、搬迁与生态措施相结合，综合应对。'}]}, {'id': 'g16', 'no': '6.3', 'subject': '地理', 'title': '防灾减灾', 'subtitle': '监测、防御、救援与自救', 'color': '#1a7474', 'points': [{'head': '① 防灾减灾的指导方针', 'body': '我国防灾减灾工作坚持<b>以防为主，防抗救相结合</b>，实行<b>统一领导、分级负责、属地管理</b>的原则，依靠<b>科技进步</b>和<b>社会力量</b>，提高全社会抵御灾害的能力。', 'tip': '方针四字记：防、抗、救、管（防为主）。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">以防为主</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">防抗救相结合</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">统一领导、分级负责</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">依靠科技与社会力量</text></svg>'}, {'head': '② 灾害监测', 'body': '建立<b>立体监测体系</b>：气象卫星、天气雷达、自动气象站监测天气；地震台网监测地壳活动；水文站监测水位流量；海洋浮标监测风暴潮、海啸；辅以<b>群测群防</b>的群专结合网络。', 'tip': '天—空—地一体化监测网络是预报预警的前提。'}, {'head': '③ 预报与预警', 'body': '在监测基础上开展<b>灾害预报</b>，并发布<b>预警信息</b>（我国气象灾害预警分<b>蓝、黄、橙、红</b>四级，红色最高）；通过广播、电视、短信、新媒体、应急广播等多渠道<b>快速传播</b>到户到人。', 'tip': '预警四级：蓝黄橙红，红色最高，务必记住顺序。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1a7474" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1a7474"/><circle cx="64.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="64.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">蓝色</text><text x="64.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">四级最低</text><circle cx="128.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="128.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">黄色</text><text x="128.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">三级</text><circle cx="192.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="192.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">橙色</text><text x="192.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">二级</text><circle cx="256.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="256.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">红色</text><text x="256.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">一级最高</text></svg>'}, {'head': '④ 防御措施——非工程性措施', 'body': '包括制定<b>法律法规与应急预案</b>、开展<b>防灾减灾宣传教育</b>、组织<b>应急演练</b>、进行<b>灾害风险评估与区划</b>、推行<b>灾害保险</b>、实施退耕还林还湖、规划避让等。', 'tip': '非工程措施关键词：法规、规划、教育、演练、保险。'}, {'head': '⑤ 防御措施——工程性措施', 'body': '修建<b>水库、堤防、分洪蓄洪区</b>防洪；建设<b>沿海防潮堤与防护林</b>抗台风风暴潮；实施<b>护坡、抗滑桩、排水沟、拦砂坝</b>治理滑坡泥石流；提高建筑<b>抗震设防标准</b>。', 'tip': '工程措施与灾害一一对应：水患—堤库；滑坡—护坡；地震—抗震。'}, {'head': '⑥ 应急救援', 'body': '灾害发生后<b>快速响应</b>：启动应急预案，组织<b>抢救生命</b>（首要任务），抢修<b>道路、通信、供水供电</b>等生命线工程，妥善安置受灾群众，防止<b>次生灾害</b>与疫情。', 'tip': '救援第一原则：生命至上，先救人再抢物。'}, {'head': '⑦ 灾后恢复重建', 'body': '开展<b>灾情评估</b>，组织<b>恢复生产、重建家园</b>，并给予<b>财政补贴、税收减免、技术支持</b>；重建中落实更高<b>防灾标准</b>，总结经验完善预案。', 'tip': '重建≠简单复原，要提高设防标准。'}, {'head': '⑧ 自救与互救', 'body': '地震：室内躲<b>承重墙墙角、坚固家具旁</b>，护住头颈，<b>不乘电梯</b>，震后有序撤离到空旷地带；被埋时保存体力、敲击求救。洪水：<b>迅速向高处转移</b>，勿贪财物。泥石流：向<b>两侧垂直于流向</b>的山坡跑，不可顺沟谷方向跑。台风：加固门窗、远离海边与广告牌。', 'tip': '常考三条：泥石流往两侧垂直方向跑、洪水往高处跑、地震不乘电梯。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">保持冷静，判明险情</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">选择正确的逃生路线</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">护住头颈，避开危险物</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">撤离后报警并相互救助</text></svg>'}], 'videos': [{'name': '《防灾减灾科普》系列片', 'type': '科普视频', 'level': '必看', 'kw': '防灾减灾 科普 应急预案 演练', 'note': '系统了解监测预警与防御体系', 'seg': '看 20 分钟', 'covers': '①②③④', 'minutes': 20}, {'name': '《地震应急救援》纪录片', 'type': '纪录片', 'level': '必看', 'kw': '地震救援 应急救援 纪录片', 'note': '了解救援流程与生命线工程抢修', 'seg': '20 分钟', 'covers': '⑤⑥⑦', 'minutes': 20}, {'name': '《家庭应急避险手册》科普', 'type': '科普视频', 'level': '补充', 'kw': '地震 自救互救 应急包 家庭 科普', 'note': '学习实用避险动作并准备家庭应急包', 'seg': '10 分钟', 'covers': '⑧', 'minutes': 10}], 'quiz': [{'q': '我国防灾减灾工作的基本方针是（\u3000）', 'o': ['以防为主，防抗救相结合', '以救为主，防救分离', '完全依靠工程措施', '只依靠政府救援'], 'a': 0, 'e': '我国坚持以防为主，防抗救相结合的方针。', 'svg': '<svg viewBox="0 0 320 116" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">以防为主</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">防抗救结合</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#1a7474" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#1a7474" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">统一领导分级负责</text></svg>'}, {'q': '我国气象灾害预警信号按照严重程度由低到高依次为（\u3000）', 'o': ['蓝色、黄色、橙色、红色', '红色、橙色、黄色、蓝色', '绿色、黄色、橙色、红色', '黄色、蓝色、橙色、红色'], 'a': 0, 'e': '预警依次为蓝、黄、橙、红四级，红色为最高级别。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#1a7474" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#1a7474"/><circle cx="64.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="64.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">蓝色</text><text x="64.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">四级最低</text><circle cx="128.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="128.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">黄色</text><text x="128.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">三级</text><circle cx="192.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="192.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">橙色</text><text x="192.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">二级</text><circle cx="256.0" cy="52" r="5" fill="#fff" stroke="#1a7474" stroke-width="2.5"/><text x="256.0" y="39" font-size="11" font-weight="700" fill="#1a7474" text-anchor="middle">红色</text><text x="256.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">一级最高</text></svg>'}, {'q': '下列属于防灾减灾非工程措施的是（\u3000）', 'o': ['制定应急预案并组织防灾演练', '修筑防洪堤', '修建水库', '建设防潮堤'], 'a': 0, 'e': '预案与演练属非工程措施；修堤、修库属工程性措施。'}, {'q': '下列属于防灾减灾工程性措施的是（\u3000）', 'o': ['修建水库和分洪蓄洪区', '开展防灾减灾宣传教育', '推行灾害保险', '制定法律法规'], 'a': 0, 'e': '水库与蓄洪区属工程措施，其余为非工程措施。'}, {'q': '地震发生时，在室内正确的避险方式是（\u3000）', 'o': ['躲在承重墙墙角或坚固家具旁，护住头颈', '立即乘电梯下楼', '跳窗逃生', '站在窗边观察'], 'a': 0, 'e': '应就近躲避于坚固处并护住头颈，震后走楼梯有序撤离，切勿乘电梯。'}, {'q': '在山区突遇泥石流，正确的逃生方向是（\u3000）', 'o': ['沿垂直于泥石流流向的两侧山坡高处跑', '顺沟谷向下游跑', '原地等待救援', '向沟谷下游游泳逃生'], 'a': 0, 'e': '应向垂直于流向的两侧高处逃离，绝不可顺沟谷方向跑。'}, {'q': '洪水中被困时的首要原则一般是（\u3000）', 'o': ['迅速向高处或坚固建筑物转移', '抓紧打捞财物', '待在地下室等待', '顺水游向下游'], 'a': 0, 'e': '洪水避险要尽快向高处转移，生命优先于财物。'}, {'q': '灾害发生后应急救援的首要任务是（\u3000）', 'o': ['抢救生命', '抢修道路', '统计财产损失', '恢复农业生产'], 'a': 0, 'e': '应急救援坚持生命至上，首要任务是搜救被困人员。'}, {'q': '台风来临前的正确准备是（\u3000）', 'o': ['加固门窗、收回阳台物品，远离海边', '去海边观浪', '在高大广告牌下避风', '打开全部窗户通风'], 'a': 0, 'e': '应加固门窗、清理高空物品并远离海边与临时构筑物。'}, {'q': '家庭储备应急包，一般不需要准备的是（\u3000）', 'o': ['大量现金与贵重首饰', '饮用水和压缩食品', '手电筒与备用电池', '急救用品和哨子'], 'a': 0, 'e': '应急包重点是水、食品、照明、急救与哨子等求救物品，而非贵重物品。'}], 'quiz_adv': [{'q': '某地同时受暴雨预警与山洪预警，最合理的响应顺序是（\u3000）', 'o': ['关注预警—停止低洼作业—向高处转移—配合救援', '照常生产—等待通知—再撤离', '先转移财物—再转移人员', '先报警—原地等待'], 'a': 0, 'e': '应先接收预警、停止危险作业、及时转移到高处并配合救援。'}, {'q': '在防灾减灾中，进行灾害风险评估与区划的主要作用是（\u3000）', 'o': ['为城乡建设选址和制定设防标准提供依据', '替代灾害预报', '彻底消除灾害', '只用于统计灾情'], 'a': 0, 'e': '风险评估与区划指导国土空间规划、工程选址与设防标准。'}, {'q': '下列关于防灾减灾宣传教育的意义，表述最恰当的是（\u3000）', 'o': ['提高公众防灾意识与自救互救能力，减少伤亡', '完全避免灾害发生', '降低灾害监测成本', '使工程措施不再必要'], 'a': 0, 'e': '宣传教育能提升公众风险意识与避险能力，从而减轻人员伤亡。'}, {'q': '灾后重建中强调提高设防标准，其根本目的是（\u3000）', 'o': ['增强承灾体的抗灾能力，减少未来损失', '降低重建速度', '减少政府投入', '改变灾害发生频率'], 'a': 0, 'e': '提高设防标准可提升抗灾能力，从而减轻再次受灾的损失。'}, {'q': '某地河流上游拟新建城镇，从防灾角度最应避免选址于（\u3000）', 'o': ['泥石流沟口与洪水行洪区', '河流两侧的阶地高处', '地势较高且排水良好的坡地', '远离活动断裂带的区域'], 'a': 0, 'e': '沟口、行洪区是泥石流与洪水的高危险区，应避让。'}, {'q': '预警信息能够发挥作用，最重要的前提是（\u3000）', 'o': ['监测准确并及时传递到户到人', '预警颜色足够醒目', '只发布给政府部门', '灾后才发布'], 'a': 0, 'e': '监测准确并快速传播到户到人，预警才能真正减少伤亡。'}, {'q': '关于地震后被埋压的自救，正确的是（\u3000）', 'o': ['保存体力，用敲击管道等方式发出求救信号', '连续大声呼喊直到救援到来', '拼命挣扎试图挣脱', '点火照明查看情况'], 'a': 0, 'e': '被埋时应保存体力、捂住口鼻，用敲击声示警，等待救援。'}, {'q': '下列措施中，既能减轻滑坡又能减少泥石流灾害的是（\u3000）', 'o': ['恢复山区植被、修建拦砂坝和排水沟', '大面积开挖坡脚修路', '向沟谷倾倒弃土', '清除全部地表植被'], 'a': 0, 'e': '植被固土、拦砂坝拦挡泥沙、排水沟疏排地表水，对二者都有效。'}, {'q': '城市防涝的海绵城市理念，其核心是（\u3000）', 'o': ['增加下渗与滞蓄，提高城市吸纳雨水的能力', '把雨水全部快速排入河道', '扩大硬化地面面积', '取消城市排水管网'], 'a': 0, 'e': '海绵城市通过透水铺装、绿地湿地等增加下渗滞蓄，减轻内涝。'}, {'q': '综合来看，提高一个地区防灾减灾能力的关键在于（\u3000）', 'o': ['监测预警、工程防御、应急管理和公众参与四方面协同', '单纯提高工程标准', '单纯依靠政府财政投入', '完全依赖国际援助'], 'a': 0, 'e': '防灾减灾是系统工程，需科技监测、工程与非工程措施、应急体系和社会参与协同。'}]}, {'id': 'g17', 'no': '6.4', 'subject': '地理', 'title': '地理信息技术在防灾减灾中的应用', 'subtitle': '遥感、全球卫星导航系统与地理信息系统', 'color': '#2a7ab8', 'points': [{'head': '① 遥感（RS）', 'body': '<b>遥感</b>是利用<b>电磁波</b>远距离探测地物，通过<b>传感器</b>（装在卫星、飞机上）记录信息，再经判读处理获取地面状况的技术。通俗理解：<b>给地球拍照</b>，具有<b>范围大、速度快、周期短、受地面条件限制少</b>的优点。', 'tip': '核心功能：获取信息（看得见的"千里眼"）。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">地物反射、辐射电磁波</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">卫星/航空传感器接收</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">数据传输至地面站</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">图像处理与判读</text></svg>'}, {'head': '② 全球卫星导航系统（GNSS）', 'body': '<b>GNSS</b>是利用卫星进行<b>定位、导航、授时</b>的系统。我国<b>北斗卫星导航系统（BDS）</b>与美国 GPS、俄罗斯 GLONASS、欧盟 Galileo 并列。核心功能：<b>在哪里</b>——提供三维坐标、速度和时间。', 'tip': '核心功能：定位导航（"指南针"）。北斗是我国自主建设的重要成果。'}, {'head': '③ 地理信息系统（GIS）', 'body': '<b>GIS</b>是在计算机软硬件支持下，对地理数据<b>输入、存储、管理、分析、输出</b>的技术系统。最大特长是<b>空间分析</b>（叠加、缓冲、网络分析、模拟），实现<b>制图与决策支持</b>。', 'tip': '核心功能：分析与管理信息（"大脑"）。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">数据采集输入</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">数据库存储管理</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">空间分析处理</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">成果输出与决策</text></svg>'}, {'head': '④ 三种技术的区别', 'body': '<b>RS 解决"是什么、在哪里分布"</b>（获取）；<b>GNSS 解决"精确位置在哪"</b>（定位）；<b>GIS 解决"意味着什么、该怎么办"</b>（分析决策）。三者功能不同、互为支撑，常组合使用。', 'tip': '一句话辨析：RS 看、GNSS 定、GIS 算。三者常组合使用。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2a7ab8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2a7ab8"/><circle cx="64.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="64.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">RS</text><text x="64.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">获取影像</text><circle cx="128.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="128.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">GNSS</text><text x="128.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">精确定位</text><circle cx="192.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="192.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">GIS</text><text x="192.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">分析决策</text><circle cx="256.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="256.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">3S</text><text x="256.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">综合应用</text></svg>'}, {'head': '⑤ RS 在防灾减灾中的应用', 'body': '① 监测<b>台风位置、移动路径与强度</b>（气象卫星云图）；② 监测<b>洪涝淹没范围</b>、干旱面积；③ 探测<b>森林草原火灾</b>热点；④ 获取滑坡体活动与<b>冰川融水</b>状况；⑤ 全天候方式可比，尤其适用于<b>大范围动态监测</b>。', 'tip': '答题关键词：大范围、快速、动态监测灾害范围。'}, {'head': '⑥ GNSS 在防灾减灾中的应用', 'body': '① 精确定位<b>受灾人员与救援车辆</b>，实现导航调度；② <b>地壳形变监测</b>（高精度测量板块位移，辅助地震监测预报）；③ 滑坡、大坝、桥梁的<b>形变预警</b>；④ 北斗<b>短报文通信</b>可在通信中断时发送位置与灾情。', 'tip': '北斗短报文是高频亮点，通信中断时仍能报平安。'}, {'head': '⑦ GIS 在防灾减灾中的应用', 'body': '① 叠加<b>地形、地质、水文、人口</b>等图层进行<b>灾害风险评估区划</b>；② 制作<b>淹没范围模拟图</b>、疏散路线图；③ 进行<b>灾情评估与统计</b>，辅助救灾物资调配；④ 建立<b>灾害数据库</b>与决策支持系统。', 'tip': '答题关键词：图层叠加、空间分析、模拟评估、辅助决策。'}, {'head': '⑧ 3S 技术综合运用案例', 'body': '以抗洪为例：<b>RS</b> 拍摄洪水淹没范围影像 → <b>GIS</b> 叠加人口、道路、堤防图层判断重灾区与疏散路线 → <b>GNSS</b> 引导救援车辆精准到达受灾点。三者组合形成<b>监测—分析—处置</b>的完整闭环。', 'tip': '综合题模板：RS 获取信息 → GIS 分析决策 → GNSS 定位执行。', 'svg': '<svg viewBox="0 0 320 150" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><rect x="18" y="10" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="28" font-size="11.5" fill="#4a4238">RS：获取灾区影像</text><path d="M160 36 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="44" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="62" font-size="11.5" fill="#4a4238">GIS：叠加图层分析评估</text><path d="M160 70 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="78" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="96" font-size="11.5" fill="#4a4238">GNSS：导航至受灾点</text><path d="M160 104 l0 6 m-4 -3 l4 3 l4 -3" stroke="#2a7ab8" stroke-width="1.6" fill="none"/><rect x="18" y="112" width="284" height="26" rx="7" fill="#fbf6ef" stroke="#2a7ab8" stroke-width="1.2"/><text x="30" y="130" font-size="11.5" fill="#4a4238">救援与重建决策</text></svg>'}], 'videos': [{'name': '《遥感是什么》科普', 'type': '科普视频', 'level': '必看', 'kw': '遥感 RS 原理 科普 高中地理', 'note': '理解遥感成像原理与应用领域', 'seg': '12 分钟', 'covers': '①⑤', 'minutes': 12}, {'name': '《北斗卫星导航系统》纪录片', 'type': '纪录片', 'level': '必看', 'kw': '北斗卫星导航系统 纪录片 应用', 'note': '理解 GNSS 定位与短报文在救灾中的作用', 'seg': '20 分钟', 'covers': '②⑥', 'minutes': 20}, {'name': '《GIS 空间分析》科普', 'type': '科普视频', 'level': '选看', 'kw': '地理信息系统 GIS 空间分析 科普', 'note': '看懂图层叠加与缓冲区分析', 'seg': '15 分钟', 'covers': '③④⑦⑧', 'minutes': 15}], 'quiz': [{'q': '能对受灾区域进行大范围、快速动态监测的技术是（\u3000）', 'o': ['遥感（RS）', '全球卫星导航系统（GNSS）', '地理信息系统（GIS）', '数字地球'], 'a': 0, 'e': '遥感可大范围、快速获取地表影像，用于动态监测灾害范围。'}, {'q': '确定某救灾车辆精确位置所用到的技术是（\u3000）', 'o': ['GNSS', 'RS', 'GIS', '雷达探测'], 'a': 0, 'e': '全球卫星导航系统用于定位与导航。'}, {'q': '下列活动中，主要依赖 GIS 实现的是（\u3000）', 'o': ['叠加图层分析洪水淹没范围并制定疏散方案', '拍摄台风云图', '确定车辆经纬度', '测量两地距离'], 'a': 0, 'e': 'GIS 擅长空间分析与图层叠加，用于辅助规划决策。'}, {'q': 'RS、GNSS、GIS 三者的功能对应关系，正确的是（\u3000）', 'o': ['RS 获取信息、GNSS 定位导航、GIS 分析处理', '三者功能完全相同', 'RS 负责数据分析', 'GIS 负责拍摄影像'], 'a': 0, 'e': 'RS 看、GNSS 定、GIS 算，三者分工明确。', 'svg': '<svg viewBox="0 0 320 118" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:auto;display:block"><line x1="16" y1="52" x2="304" y2="52" stroke="#2a7ab8" stroke-width="2.5" stroke-linecap="round"/><path d="M304 52 l-9 -5 l0 10 z" fill="#2a7ab8"/><circle cx="80.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="80.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">RS</text><text x="80.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">获取影像</text><circle cx="160.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="160.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">GNSS</text><text x="160.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">精确定位</text><circle cx="240.0" cy="52" r="5" fill="#fff" stroke="#2a7ab8" stroke-width="2.5"/><text x="240.0" y="39" font-size="11" font-weight="700" fill="#2a7ab8" text-anchor="middle">GIS</text><text x="240.0" y="71" font-size="9.5" fill="#6b6357" text-anchor="middle">分析决策</text></svg>'}, {'q': '通过气象卫星云图判断台风位置和移动路径，主要利用（\u3000）', 'o': ['RS', 'GNSS', 'GIS', 'GPS 授时'], 'a': 0, 'e': '卫星云图属遥感影像，可用于监测台风位置与路径。'}, {'q': '我国自主建设的全球卫星导航系统是（\u3000）', 'o': ['北斗卫星导航系统（BDS）', 'GPS', '伽利略系统', '格洛纳斯系统'], 'a': 0, 'e': '我国自主建设的是北斗卫星导航系统。'}, {'q': '利用卫星影像快速估算森林火灾的过火面积，主要用到（\u3000）', 'o': ['RS', 'GNSS', 'GIS 制图所学代码', '人工普查'], 'a': 0, 'e': '通过遥感影像判读可快速获取过火面积。'}, {'q': 'GIS 最大的特长是（\u3000）', 'o': ['空间分析与图层叠加', '拍摄地表照片', '提供经纬度坐标', '发射导航信号'], 'a': 0, 'e': 'GIS 的核心能力是空间数据的管理、分析与制图表达。'}, {'q': '在抗震救灾中，利用高精度 GNSS 长期监测量数据，可直接服务于（\u3000）', 'o': ['地壳形变监测与地震危险性分析', '预测台风路径', '拍摄云图', '统计人口数量'], 'a': 0, 'e': '高精度 GNSS 可监测地壳微小形变，为地震危险性分析提供依据。'}, {'q': '区分 RS 与 GIS，最简洁的判断标准是（\u3000）', 'o': ['RS 获取信息，GIS 分析处理信息', 'RS 更精确', 'RS 只用于军事', 'GIS 不需要计算机'], 'a': 0, 'e': 'RS 负责获取，GIS 负责存储管理与空间分析。'}], 'quiz_adv': [{'q': '某地为制定洪水疏散预案，将地形、人口密度、道路网图层叠加分析，应主要使用（\u3000）', 'o': ['GIS', 'RS', 'GNSS', 'RS 与 GNSS 的结合即可'], 'a': 0, 'e': '多图层叠加的空间分析是 GIS 的典型功能。'}, {'q': '在通信中断的震区，救援人员仍能向外发送位置与灾情，依靠的是北斗的（\u3000）', 'o': ['短报文通信功能', '气象探测功能', '遥感成像功能', '授时功能'], 'a': 0, 'e': '北斗系统具备短报文通信能力，可在无移动信号时传递简短信息。'}, {'q': '要实时、连续地掌握某座滑坡体的微小位移变化，最适合采用（\u3000）', 'o': ['高精度 GNSS 连续观测', '每年一次的 RS 影像', '纸质地形图', '人工巡查'], 'a': 0, 'e': 'GNSS 可实现毫米级、连续实时的形变监测，适合滑坡预警。'}, {'q': '台风来临前迅速确定低洼区需要转移的人口数量，最合理的做法是（\u3000）', 'o': ['用 GIS 叠加淹没模拟范围与人口分布图层进行统计', '只凭遥感影像目视估计', '挨家挨户口头询问', '用 GNSS 逐点记录'], 'a': 0, 'e': 'GIS 可把淹没范围图层与人口数据叠加，快速统计需转移人数。'}, {'q': '下列技术与其功能配对中，错误的是（\u3000）', 'o': ['RS——提供三维坐标定位', 'GNSS——定位导航授时', 'GIS——空间分析决策', 'RS——动态监测'], 'a': 0, 'e': '提供定位坐标的是 GNSS，RS 只负责获取地表信息。'}, {'q': '遥感能够发现森林大火隐患（热点），其物理依据是（\u3000）', 'o': ['物体温度不同，辐射的电磁波特征不同', '森林会反射可见光', '树木会发出声音', '遥感使用了超声波'], 'a': 0, 'e': '不同地物辐射电磁波的波段特征不同，温度异常区可被红外波段探测。'}, {'q': '关于 RS 在防汛中的应用，下列说法正确的是（\u3000）', 'o': ['可全天候、连续监测水体范围变化，评估淹没面积', '能直接阻止洪水发生', '可以替代堤防工程', '只能用于白天晴好天气'], 'a': 0, 'e': '遥感可穿透云层（雷达遥感）并连续监测，用于评估淹没范围。'}, {'q': '某 GIS 项目中需要分析距河流 500 米范围内的村庄，应使用的分析方法是（\u3000）', 'o': ['缓冲区分析', '地形剖面分析', '数据统计排序', '遥感解译'], 'a': 0, 'e': '在河流两侧建立 500 米缓冲带再叠加村庄图层，属缓冲区分析。'}, {'q': '3S 技术支持下的灾害应急流程，合理的顺序是（\u3000）', 'o': ['RS 获取灾情影像 → GIS 分析评估 → GNSS 引导救援', 'GIS 拍摄影像 → RS 定位 → GNSS 分析', 'GNSS 获取影像 → RS 分析 → GIS 定位', '三者各自独立完成工作'], 'a': 0, 'e': 'RS 获取信息，GIS 分析评估，GNSS 定位导航引导救援。'}, {'q': '综合评价 3S 技术在防灾减灾中的意义，最准确的是（\u3000）', 'o': ['提高灾害监测、预警、评估与救援的效率和科学性，减少灾害损失', '能彻底消除自然灾害', '使工程防御措施不再必要', '只对发达国家有意义'], 'a': 0, 'e': '3S 技术贯穿灾害全过程的监测—评估—救援环节，有效提升防灾减灾能力。'}]}]
